programs.sol:
"""A lexical 神 / shen feature, with weaker spirit-related vocabulary.

The strongest cue is 神 ('spirit, deity'). The feature also recognizes its
split UTF-8 spelling and some cross-token spellings of 'shen'. Compounds and
cognates are weaker; dictionary glosses distinguish the Chinese compounds.
Small spirit/mind cues and negative 'short-' and 'spiritual' cues fill out
the approximation. State only joins spellings and resets between documents;
this does not attempt to classify a document's religion.
"""
import cedict

READS = ()
GOD_BYTES = '神'.encode('utf-8')


def chinese_compound(word):
    # Classify compounds by their dictionary meaning, not by token identity.
    gloss = ' '.join(cedict.glosses(word.removeprefix('的'))).lower()
    if 'goddess' in gloss:
        return 4.3
    if 'expression' in gloss or 'glance' in gloss:
        return 4.0
    if 'nerve' in gloss:
        return 2.7 if len(word) <= 3 else 0.0
    if any(cue in gloss for cue in ('spirit', 'mental', 'magical', 'miraculous')):
        return 2.1
    return 0.8


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else b''
    byte_tail = carry[2] if same_doc else b''
    raw = prefix.token_bytes[-1]
    word = prefix.token_strings[-1].strip()
    joined = byte_tail + raw
    prev_word = previous.decode('utf-8', 'replace').lower()
    lower = word.lower()
    value = 0.0

    if word == '神':
        value = 8.1
    elif '神' in word:
        value = chinese_compound(word)
    elif joined.endswith(GOD_BYTES) and not raw.endswith(GOD_BYTES):
        value = 12.4  # Completing a 神 split across byte tokens.
    elif joined.endswith(GOD_BYTES[:2]) and not byte_tail.endswith(GOD_BYTES[:2]):
        value = 6.5  # The still-incomplete ritual-character byte prefix.
    elif joined.endswith('靈'.encode('utf-8')) and '�' in word:
        value = 4.7
    elif lower == 'shen':
        value = 4.1
    elif not raw[:1].isspace() and prev_word.endswith('sh'):
        # 'shen' assembled from two pieces; longer pieces are weaker cues.
        if prev_word.strip() == 'sh' and lower.startswith('en'):
            if lower.startswith('eng'):  # sheng is not the same syllable
                value = 1.4
            elif len(lower) > 4:
                value = 0.8
            else:
                value = 8.5 / (1.0 + 0.4 * (len(lower) - 2))
        elif lower == 'en' and not previous[:1].isspace():
            value = 3.2
        elif lower.startswith('ort'):
            value = -3.2  # Contrast with the competing English 'short-' spelling.
    elif lower == 'en' and prev_word.endswith(('sch', 'š')):
        value = 1.0
    elif word == 'ن' and not raw[:1].isspace() and prev_word.endswith('ش'):
        value = 2.5  # Persian شن (shen), even though it means 'sand'.
    elif word == 'thần':
        value = 4.8  # Vietnamese Sino-Vietnamese cognate of 神.
    elif word == '신':
        value = 3.6 if raw.startswith(b' ') else 1.8
    elif lower in {'spirit', 'spirits'}:
        value = 0.35
    elif lower in {'spiritual', 'spirituality', 'spiritually'}:
        value = -0.18
    elif lower == 'neural':
        value = 1.0
    elif word in {'靈', '灵'}:
        value = 0.3
    elif word in {'精', '魂'}:
        value = 0.75
    elif word.removeprefix('的') == '情':
        value = 0.45

    return (doc, raw[-12:], joined[-3:]), value

programs.haiku:
"""Spirit/god words. The component fires when a token completes a word for "god" or "spirit":
the character 神 (Chinese/Japanese) most of all, weaker on words built on it (女神 goddess,
眼神 look, 精神 spirit, 神经), on Korean 신 and Vietnamese thần, and on the English sound
"shen" (Shen, Shenandoah). Everything else is about zero."""
READS = ()

def step(carry, prefix, upstream):
    text = prefix.text_prefixes[prefix.position]
    stable = text.rstrip("�")   # text decoded so far, without an unfinished character
    before = carry or ""
    new = stable[len(before):] if stable.startswith(before) else ""  # characters this token completes
    if new == "神":
        value = 8.0
    elif new.endswith("神"):
        value = 3.0
    elif "thần" in new.lower():
        value = 5.0
    elif new.endswith("신"):
        value = 2.7
    elif stable.lower().endswith("shen"):
        value = 4.5
    else:
        value = 0.0
    return stable, value

programs.sol:
"""Approximate a local k-spelling feature.

Long-vowel spellings before k are positive, especially across token pieces;
t/d + k clusters are negative. English frequency suppresses familiar words.
Short English suffixes can retain the positive signal. A Japanese long-vowel
mark before a k-syllable is positive too. This is a spelling approximation,
not a list of particular words or a complete account of lexical exceptions.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
SUFFIXES = {'', 's', 'es', 'e', 'y', 'ed', 'er', 'ers', 'ing'}
# Spelling family: terminal word, nonterminal word, continuing token piece.
FAMILIES = {
    'eak': (2.2, 0.0, 1.0),
    'eek': (1.7, 0.3, 0.5),
    'oak': (1.8, 0.0, 3.0),
    'ake': (0.0, 0.0, 0.2),
    'oke': (0.0, 0.0, 0.3),
}

@lru_cache(maxsize=32768)
def roman(text):
    return anyascii(text).lower()

@lru_cache(maxsize=32768)
def rarity(word):
    return max(0.0, min(3.0, 5.1 - zipf_frequency(word, 'en')))


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    a, p = roman(s), roman(previous)
    latin = s.isascii() and previous.isascii()
    continues = bool(a and p and a[0].isalpha() and p[-1].isalpha())
    words = re.findall('[a-z]+', a)
    w = next((word for word in reversed(words) if 'k' in word), '')
    last_word = re.search('[a-z]+$', p)
    last_word = last_word[0] if last_word else ''
    k = w.find('k')
    ending = w[k + 1:] if k >= 0 else ''
    short = len(w) <= 4
    syllable = k == 0 and (len(w) == 1 or
                          (len(w) == 2 and w[1] in 'aeiouy'))
    regular = k >= 0 and ending in SUFFIXES

    sdk = 'sdk' in w or (continues and p.endswith('s') and w.startswith('dk'))
    value = -4.2 * sdk
    if short and 'sdk' not in w:
        value -= 0.6 * ('tk' in w) + 0.9 * ('dk' in w) + 1.8 * ('DK' in s)
    if continues and w == 'dk' and p[-1] not in 'aeious':
        value -= 0.7
    if previous.endswith('ー') and s and s[0] in 'カキクケコかきくけこ':
        value += 2.0

    if continues:
        if syllable:
            value -= 2.2 * p.endswith('d')
            value -= (2.5 if latin else 1.0) * p.endswith('t')
            if latin:
                value -= 0.9 * ('d' in last_word) + 0.6 * ('t' in last_word)
                value += 1.0 * p.endswith('e')
        if short and k == 1 and w[0] in 'aeiou' and p.endswith(('t', 'd')):
            value -= 0.2
        if latin:
            if p.endswith('c') and regular and short and (k == 0 or w[k-1] not in 'dt'):
                value += 1.4
            if regular:
                if p.endswith('e') and w.startswith(('ak', 'ek')):
                    value += 4.2
                if p.endswith('o') and w.startswith('ak'):
                    value += 4.8
                if p.endswith('ee') and w.startswith('k'):
                    value += 3.9

    for spelling, (terminal, other, fragment) in FAMILIES.items():
        if spelling in w:
            if continues and latin:
                value += fragment * regular
            elif s.isascii():
                value += rarity(w) * (terminal if ending in {'', 's'} else other)

    if continues and latin and 'k' not in a and a in SUFFIXES and last_word.endswith('k'):
        value += 0.15 + 0.45 * (a == 'y')
        value += 1.6 * last_word.endswith('eak') + 0.5 * last_word.endswith('eek')
    return None, float(value)

"""A signed x/xi detector, dominated by hexadecimal byte escapes.

Negative values mark escape starts and selected leading hex digits. Their
strength depends on recent encoded bytes and token boundaries. A smaller,
approximate positive channel covers xi spellings and Mandarin pronunciation
cues. Other text receives zero. Magnitudes are calibrated on training text.

State is only 24 text characters, three token strings and three raw bytes;
it resets at document boundaries.
"""
from functools import lru_cache
from pypinyin import lazy_pinyin, Style
import regex
import unicodedata
import re

READS = ()
HEX_DIGITS = frozenset("0123456789abcdefABCDEF")


@lru_cache(maxsize=8192)
def lexical_value(s):
    if s == '西':                     # west
        return 5.4
    if s == '希':                     # hope; also used to transcribe xi
        return 6.4
    if regex.search(r'\p{Script=Han}', s):
        if len(s) == 1:
            syllable = lazy_pinyin(s, style=Style.TONE3)[0]
            return {'xi1': 1.5, 'xie2': 1.2, 'xu1': 0.5}.get(syllable, 0.0)
        if '西' in s:
            return 3.2 if s == '西方' else 1.0
    if s == ' Xi':
        return 5.7
    if s.strip() in ('Xi', 'XI', 'xi'):
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is not None and carry[0] == doc:
        tail, recent, raw_tail = carry[1:]
    else:
        tail, recent, raw_tail = '', (), b''
    s = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    value = lexical_value(s)
    # Recover a Han character when its UTF-8 bytes straddle token boundaries.
    joined = raw_tail + raw
    if '\ufffd' in s:
        text = joined.decode('utf-8', errors='ignore')
        if text and joined.endswith(text[-1].encode('utf-8')):
            value = lexical_value(text[-1])
    # Token carrying the preceding byte's x, before its final hex digit.
    lead = recent[-2] if len(recent) > 1 and recent[-1] in HEX_DIGITS else ''
    prior_lead = (
        recent[-3] if len(recent) > 2 and recent[-2] in HEX_DIGITS else ''
    )
    if s == '\\x':
        # An escape continuing a byte stream is stronger than an isolated one.
        value = -7.3 if re.search(r'\\x[0-9a-fA-F]{2}$', tail) else -3.6
        if lead == 'xe':
            value = -10.5
        elif lead == '\\xc':
            value = -9.9
    elif s.startswith('\\x'):
        nibble = s[2:].lower()
        value = {
            'a': -10.7, 'b': -11.0, 'c': -2.4, 'e': -1.6
        }.get(nibble, 0.0)
        if nibble == 'a':
            value = (
                -14.7 if lead == 'xc' else
                -9.8 if lead == '\\xc' else -11.5
            )
    elif tail.endswith('\\') and s in ('x', 'xc', 'xd', 'xe'):
        value = -6.5 if s == 'xc' else -5.5
    elif tail.endswith('\\x') and len(s) == 1:
        value = {'0': -3.3, '1': -5.0, '8': -8.3, '9': -12.0}.get(s, 0.0)
        if s == '8':
            value = (
                -10.7 if prior_lead == 'xe' else
                -6.9 if prior_lead == '\\xe' else -9.3
            )
        elif s == '9' and prior_lead == '\\xe':
            value = -7.4
    elif tail.endswith('0x') and s in ('0', '8', '9'):
        value = {'0': -0.5, '8': -2.5, '9': -4.8}[s]
    elif s == 'x' and re.search(r'x[ce89][0-9a-f]$', tail):
        value = -11.0               # byte escapes with missing backslashes
    elif s == 'x' and tail.endswith('0'):
        value = -0.8
    elif s == 'xi' and tail and tail[-1].isalpha():
        value = 5.5
    elif len(s) == 1 and tail.endswith(('x', 'X', 'ξ')):
        plain = unicodedata.normalize('NFD', s)[0]
        if plain in ('i', 'ι'):
            value = 5.0
    state = (doc, (tail + s)[-24:], (recent + (s,))[-3:], joined[-3:])
    return state, float(value)

"""Separate TeX line/layout notation from doubled escapes in source code.

Doubled backslashes in recent mathematical markup are positive, but those
in escaped source strings are negative. TeX's other line-layout commands
also respond. The first whitespace token after a TeX row break inherits
part of its response. Carry is reset at document boundaries.

Small extra rules cover initial comment/declaration/newline markers and
documents made of middle-dot filler; otherwise the prediction is zero.
This deliberately omits the component's many small, word-specific responses.
"""
import re

READS = ()

TEX = re.compile(
    r'\\(?:begin|end|frac|dfrac|tfrac|left|right|mathrm|mathbf|'
    r'text|texttt|textsc|mbox|sqrt|sum|int|lim|rightarrow|partial|'
    r'overline|equiv|bmod|cdot|alpha|beta|gamma|delta|epsilon|'
    r'theta|lambda|sigma|pm|quad|qquad|dots|nonumber|hline)\b'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, recent, last_break = carry
    s = prefix.token_strings[-1]
    math = bool(TEX.search(recent))
    value = 0.0
    row_break = 0.0

    if '\\\\' in s:
        if not recent:
            value = 1.77 if len(s) >= 4 else 0.73
        elif '\n' in s or '\r' in s:
            value = 1.7
        elif s.endswith(('.', '/', '"')):
            value = 0.0
        elif math:
            value = 2.15 if s.startswith(' ') else 1.95
            # Closely spaced row separators give a weaker response.
            if '\\\\' in recent[-20:]:
                value *= 0.73
        elif '\\\\\\\\' in s:
            value = -0.2
        else:
            value = -0.72
            if s.startswith('(') or recent.endswith('\\"'):
                value = -1.2
            elif s.startswith('}'):
                value = -1.1
        row_break = max(0.0, value) if math else 0.0
    elif recent.endswith('\\') and s == 'non':
        value = 1.45             # Beginning of \nonumber.
    elif recent.endswith('\\non') and s == 'umber':
        value = -0.2
    elif recent.endswith('\\') and s == 'cr':
        value = 3.9              # TeX carriage return.
    elif recent.endswith('\\') and s == 'h':
        value = 1.25             # Beginning of \hline or \hfill.
    elif recent.endswith('\\h') and s in ('line', 'fill'):
        value = 1.5 if s == 'line' else 0.3
    elif recent.endswith('\\') and s == 'par':
        value = 1.2
    elif recent.endswith('\\') and s == 'tab':
        value = 1.2              # Beginning of \tabularnewline.
    elif recent.endswith('\\tabular') and s == 'newline':
        value = 1.9
    elif last_break and (s.isspace() or s.strip() == '\\'):
        value = 0.4 * last_break
    elif len(s) >= 2 and not s.strip('·') and not recent.strip('·'):
        value = -2.16
    elif not recent:
        if s.startswith('//'):
            value = -6.9 if '\n' in s else -1.4
        elif s == '<!':
            value = -7.5
        elif s == '\r\n':
            value = 1.8
    elif recent in ('//\n', '//\r\n') and s == '//':
        value = -1.5
    elif recent in ('/*\n', '/*\r\n') and s == ' *':
        value = -1.0

    return (doc, (recent + s)[-600:], row_break), value

"""A document-opening detector with a few unusually strong continuations.

Use a small negative opening-token baseline, also while that opening token
repeats. Recognize initial `12`, `Title:`, `{[`, and the water-related prefix
`Hydro`, plus initial carriage returns, centered-dot runs and comment markers.
Elsewhere predict almost zero, except for the forum heading `Similar Topics`
and the subword completing `favorite`. These rules leave most small,
context-dependent fluctuations unexplained.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous, repeated = 0, '', True
    else:
        age, previous = carry[1] + 1, carry[2]
        repeated = carry[3] and token == previous

    value = -0.0014
    if repeated:
        value = -0.23
        if token.isascii() and token.isdigit():
            value = -0.35
        if token == '1':
            value = -0.346
        elif token == '{':
            value = -0.484
        elif token == '\r':
            value = 2.273
        elif token == '··':
            value = 0.616
        elif token == '//\n':
            value = 2.665
    if age == 1:
        if previous == '1' and token == '2':
            value = 2.983
        elif previous == 'Title' and token == ':':
            value = 2.117
        elif previous == '{' and token == '[':
            value = 2.088
        elif previous == 'Hy' and token == 'dro':
            value = 5.39
    if (token == 'Topics' and age >= 2 and previous == '\n'
            and prefix.token_strings[-3].strip() == 'Similar'):
        value = -0.64
    elif token == 'avorite' and previous.endswith('f'):
        value = 1.14
    return (doc, age, token, repeated), value

"""A small approximation using document openings and machine-text boundaries.

The words public/private at the start of a snippet and the issue-comment opening
have especially large negative responses. Ordinary tokens stay near zero.
Smaller rules describe chat/tool delimiters, title fields, Java namespaces,
URL protocols and email redactions. Unmatched tokens use fixed defaults;
most lexical variation is not reproduced.
"""
READS = ()

CHAT_BOUNDARIES = {
    '<|im_start|>': -0.035,
    '<|im_end|>': -0.055,
    '<tool_call>': 0.044,
    '</tool_call>': 0.005,
    '<tool_response>': -0.080,
    '</tool_response>': 0.064,
    '</think>': 0.066,
}


def first_token(token):
    """Coarse opening-token classes, with a few source/header exceptions."""
    if token in {'public', 'private'}:
        return -2.89
    if token == 'default':
        return -1.67
    if token in {'protected', 'static', 'final', 'const'}:
        return -0.80
    if token in {'int', 'void', 'boolean', 'char', 'float',
                 'double', 'short', 'long', 'byte'}:
        return -0.65
    if token in {'import', 'using', 'template', 'export'}:
        return -0.65
    if token in {'var', 'function'}:
        return -0.32
    if token in {'class', 'struct'}:
        return 1.20
    if token in {'package', 'def', 'from', 'if', 'while', 'try'}:
        return 0.45
    if token == '<':
        return -0.48
    if token == '#':
        return -0.38
    if token == '<|im_start|>':
        return -0.21
    if token in {'user', 'assistant'}:
        return 0.84 if token == 'user' else -0.60
    return 0.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, opening, previous = 0, '', ''
    else:
        _, position, opening, previous = carry

    value = (first_token(token) if position == 0
             else CHAT_BOUNDARIES.get(token, 0.0003))
    if opening == '<' and token == 'issue':
        value = -0.24
    elif opening == '<issue_start><' and token == 'issue':
        value = -2.88
    elif opening == '<issue_start><issue_comment' and token == '>Title':
        value = -0.64
    elif opening == '<issue_start><issue_comment>Title' and token == ':':
        value = 0.27
    elif opening == 'Title' and token == ':':
        value = -1.067
    elif opening == '---\ntitle' and token == ':':
        value = -0.708
    elif opening == 'package' and token == ' com':
        value = -0.617
    elif previous.strip() == 'import' and token.strip() in {'com', 'org'}:
        value = 0.18
    elif previous.strip() in {'java', 'javax'} and token.startswith('.'):
        value = 0.20
    elif token == '://' and previous.strip() in {'http', 'https'}:
        value = -0.13
    elif previous.endswith('@example') and token in {'.com', '.org'}:
        value = -0.42
    elif previous == 'email' and token == ' protected':
        value = -0.62  # The web-text redaction [email protected].
    elif previous == 'username' and token == '_':
        value = -0.50

    opening = opening + token if position < 8 else ''
    return (doc, position + 1, opening, token), value

programs.haiku:
"""Layer 1 MLP down-projection, component 5642: a document-start detector.

What it does
------------
Almost everywhere this component is quiet (typical |activation| about 0.04).
Its clear response is at the first token of each document, the token right
after a document break, where attention and positions restart. There its
value depends on what the token looks like:

* code-like tokens (identifier fragments with underscores, brackets, dots,
  keywords such as `private`, `public`, `bool`) push it negative;
* CJK characters, printf-style codes such as `%d`, and plain word pieces
  (no leading space) push it positive;
* tokens with a leading space, and whitespace, sit near zero.

Everywhere else the program predicts 0. The rule is a rough guide: it is
shrunk by SCALE because the true document-start value is token-specific.
"""

import re

READS = ()

SCALE = 0.7
CJK = re.compile(r"[぀-ヿ㐀-鿿가-힯豈-﫿]")
CODE_WORDS = {
    "private", "public", "protected", "static", "void", "virtual", "bool",
    "boolean", "int", "float", "double", "string", "char", "using", "class",
    "return", "auto", "default", "explicit", "const", "var", "let", "def",
    "self", "struct", "enum", "new", "null", "true", "false", "import",
}


def looks_like_code(token):
    body = token.strip()
    return (
        "_" in token
        or body[:1] in ("(", ".", "{", "[", "<")
        or body in CODE_WORDS
        or ";" in token
        or "\t" in token
    )


def doc_start_value(token):
    """Activation predicted at a document's first token, from its text."""
    body = token.strip()
    value = 0.10
    if looks_like_code(token):
        value -= 0.18
    if CJK.search(token):
        value += 0.13
    if re.fullmatch(r"%[a-zA-Z]", body):
        value += 1.0
    if token.startswith(" "):
        value -= 0.05
    elif body[:1].isalpha() and body[:1].isupper():
        value += 0.13
    elif body[:1].isalpha():
        value += 0.10
    if len(body) == 1:
        value += 0.08
    return value


def step(carry, prefix, upstream):
    """Predict this position's activation: nonzero only at a document start."""
    t = prefix.position
    starts_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_doc:
        return None, 0.0
    return None, SCALE * doc_start_value(prefix.token_strings[-1])

programs.sol:
"""Approximate a code-layout and declaration signal.

Horizontal indentation and declaration modifiers receive negative values,
stronger in recent semicolon-delimited code. Backtick boundaries and a few
code punctuation forms have separate rules. Other tokens predict zero.
An otherwise unhandled document-initial token gets a small positive value.
Only a bounded recent-text buffer and the current line are retained; a new
packed document resets both. Constants are fitted on training text.
"""
import re

READS = ()
MODIFIERS = {
    'private', 'protected', 'public', 'static', 'final', 'const',
    'extern',
}
DECLARATION = re.compile(
    r'\b(private|public|protected|class|void|namespace|#include)\b'
)
ATTRIBUTE_LINE = re.compile(r'\s*(\[[^\]]+\]\s*)+')
NAMESPACE_LINE = re.compile(r'\s*\w+(::\w+)*')


def indentation(spaces, tabs, start, semis, braces):
    # Four-space indentation often leaves its last space on the next token.
    boundary = (spaces + 1) % 4 == 0
    if start:
        if semis == 0:
            if boundary:
                return -0.49 if spaces <= 5 else -0.82
            return -0.65 if tabs else -0.07
        if spaces <= 6:
