# Square-root symbols.
ROOTS = {"sqrt", " sqrt", "√"}
# LaTeX math-formatting tokens that usually appear in formulas.
MATH_MARKUP = {"frac", "_{", "}_{", "boxed", "text", "mathrm", "bf", "symbol", "mb", "phant"}


