    elif token == '范围':
        value = 2.2
    elif token == '范围内':
        value = 1.3
    elif token.endswith(('围', '圍')):
        value = 0.5

    # Covering, especially comprehensive coverage.
    elif token in ('盖', '蓋') or token.startswith(
        ('覆盖', '涵盖', '全覆盖', '掩盖', '加盖')
    ):
        value = -0.6
        if token.startswith(('覆盖', '涵盖')):
            value = -1.9
        if token == '全覆盖':
            value = -2.9

    # Brief moments, glances, and counted seconds or drops.
    elif token in ('眼', '瞬', '瞬间', '一眼'):
        value = -0.3
        if tail.endswith(('转眼', '轉眼')):
            value = -6.2
        elif tail.endswith(('转瞬', '轉瞬')):
            value = -3.8
        elif token in ('瞬间', '一眼') or tail.endswith(('一眼', '一瞬')):
            value = -1.1
    elif token in ('秒', '滴'):
        value = -0.3 if token == '秒' else 0.0
        if previous and previous[-1] in '一二三四五六七八九十几數数点點':
            value = -1.7 if token == '秒' else -2.3
        elif previous and previous[-1].isdigit():
            value = -0.45

    return (doc, tail, pending), value

programs.haiku:
"""Layer-1 MLP component 5653, as a few word-family detectors.

The component is near zero almost everywhere. Its large values come from a few
meaning families of Chinese words, so the program names those families and gives
each token its typical value:

  faint or dizzy (晕, 昏):                    strongly positive
  enclosure and range (围, 圍, 范围, 外围):   positive
  worry (忧, 憂, 慮):                         positive
  search (搜):                                weakly positive
  cover (覆盖, 涵盖, 掩, 盖):                 negative

On the first token of each document, which has no context, it dips negative.
Everything else predicts 0.
"""

READS = ()

FAINT = {"晕": 5.0, "昏": 5.0}
ENCLOSE = {"围": 3.0, "圍": 3.0, "范围": 2.5, "外围": 3.5, "范围内": 1.0}
WORRY = {"忧": 2.0, "憂": 2.0, "慮": 1.5}
SEARCH = {"搜": 1.0}
COVER = {"覆盖": -2.0, "涵盖": -2.0, "盖": -1.0, "掩": -1.0}
DOC_START = -0.19
FAMILIES = (FAINT, ENCLOSE, WORRY, SEARCH, COVER)


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    if prefix.position == 0 or docs[-1] != docs[-2]:
        return None, DOC_START
    tok = prefix.token_strings[-1]
    for family in FAMILIES:
        if tok in family:
            return None, family[tok]
    return None, 0.0

programs.sol:
"""A local signal for deductions and mathematical phrasing.

Conclusion words are negative, especially after commas, at paragraph starts,
and near mathematical notation.  Ordinary temporal/degree uses are weaker.
Short definition/question phrases are also negative; arithmetic expressions
and aggregate phrases are positive.  This is an approximation, not a parser.
"""
READS = ()

MATH_WORDS = set('''equation equations polynomial polynomials squared integer
integers theorem proof formula coefficient coefficients variable variables
matrix derivative integral solution solve'''.split())
AUXILIARIES = set('''and or is are was were be been do doing did can will would
shall should not'''.split())

# Each row: basic, nearby-math, capitalized, after-comma, paragraph-start.
CONCLUSIONS = {
    'so':         (-.28, -.78, -.47, -.65, -.41),
    'then':       (-.20, -1.25, -.71, -.87, -.30),
    'thus':       (-.15, -.59, -.33, -.25, -.39),
    'therefore':  (-.25, -.56, -.44, -.21, -.44),
    'hence':      (-.53, -.53, -.29, -.46, -.43),
}

# The word before 'that': basic and nearby-math contributions.
THAT_PHRASES = {
    'such': (-1.23, -.68),
    'so': (-.45, -1.22),
    'suppose': (-1.30, -.05),
    'assume': (-.48, -.52),
    'follows': (-1.68, -1.14),
    'note': (-.39, -.30),
    'means': (-.28, -.63),
    'show': (-.08, -.83),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, history, last_value = '', (), 0.
    else:
        previous, history, last_value = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    prev = previous.strip().lower()
    math = min(1., sum(history) / 8.)
    value = 0.

    if lower in CONCLUSIONS and not word.isupper():
        base, topical, capital, comma, paragraph = CONCLUSIONS[lower]
        value = base + topical * math
        if word[0].isupper():
            value += capital
        if ',' in previous:
            value += comma
        if '\n\n' in previous:
            value += paragraph
        if prev in AUXILIARIES:
            value += .35 if lower in {'so', 'then', 'hence'} else .20
        if not token[:1].isspace():
            value += {'so': .10, 'then': .25, 'therefore': .16}.get(lower, 0.)
    elif word == ',' and prev in CONCLUSIONS:
        value = (.45 if prev in {'so', 'then'} else .70) * last_value
    elif lower in {'let', 'but', 'also', 'given'} and word[:1].isupper():
        if not token[:1].isspace():
            base, topical = {
                'let': (-.25, -.26), 'but': (-.28, -1.28),
                'also': (-.48, -.95), 'given': (-.38, .21),
            }[lower]
            value = base + topical * math
    elif lower in {'satisfy', 'satisfies', 'satisfying'}:
        value = -.73 - .46 * math
    elif lower in {'solve', 'simplify', 'determine', 'calculate'}:
        value = -.11 - .57 * math
    elif lower in {'gives', 'implies', 'where'}:
        base, topical = {
            'gives': (-.30, -.62), 'implies': (-.23, -.30),
            'where': (-.09, -.37),
        }[lower]
        value = base + topical * math
    elif lower == 'have' and prev == 'we':
        value = -.45 - 2.22 * math - .45 * (previous == 'We')
    elif lower in {'get', 'set', 'obtain', 'had'} and prev == 'we':
        value = -.31 - .94 * math
    elif token == ' that':
        base, topical = THAT_PHRASES.get(prev, (-.04, 0.))
        value = base + topical * math
    elif token in {' is', ' are'} and prev in {'what', 'that'}:
        value = -.51 - 1.50 * math if prev == 'what' else -.05 - .46 * math
        if previous == ' What':
            value -= .53
    elif token == ' by' and prev in {'given', 'defined', 'represented', 'described'}:
        value = -1.05 - .96 * math
    elif token == ' of':
        if prev in {'value', 'expansion'}:
            value = -.41 - .57 * math
        elif prev in {'sum', 'product', 'products', 'combination', 'union', 'succession'}:
            value = .58 + .31 * math
    elif token == '**':
        value = .09 + 1.07 * math
        p = previous.strip()
        if p and (p[-1].isalnum() or p[-1] == ')'):
            value += .28
        if p.startswith('*'):
            value += .84
    elif token == ' **':
        value = .18 + .83 * math
    elif lower in {'term', 'terms'} and prev != 'in':
        value = .17 + .35 * math
    elif lower in {'squared', 'subtract', 'adding', 'combine', 'multiplied',
                   'multiplying', 'rounded'}:
        value = .25 + .68 * math
    elif word in {'⇒', '=>', '→'}:
        value = -.07 - .23 * math

    is_math = float(any(c in token for c in '$=+^') or lower in MATH_WORDS)
    history = (*history[-63:], is_math)
    return (doc, token, history, value), value

"""A spelling-based approximation to the writing/script response.

Complete English word forms respond differently from divided roots. For
scr/schr/skr and related spellings, the response depends on how far the
syllable has unfolded. A few script translations are included; split
crate/crater spellings have the opposite sign. Fine context effects are not
modeled. Only an 80-byte tail is carried, reset at document boundaries.
"""
import re
import unicodedata

READS = ()

WRITE_FORMS = {
    'write': -0.82, 'writes': -0.38, 'writing': -0.99,
    'writ': -1.04, 'written': -0.31, 'wrote': -0.37,
    'rewritten': -0.62, 'writer': -0.10, 'writers': -0.14,
}
COMPOUNDS = {
    'write': -3.70, 'writing': -4.37, 'writer': -4.32,
    'written': -0.70,
}
SCRIPT_FORMS = {
    'script': -2.16, 'scripts': -0.96, 'scripting': -3.68,
    'scripture': -1.16, 'scriptures': -1.23,
}
# Columns: consonant cluster, following vowel, stem, later ending.
ROOTS = {
    'german-cluster': (-3.38, -1.18, -0.50, 0.05),
    'german-script': (0.0, -8.25, -4.43, 0.02),
    'german-writing': (0.0, -4.67, -3.56, -2.06),
    'romance-writing': (-1.10, -5.23, -2.57, -0.85),
    'prefixed-scribere': (0.0, -10.47, -4.92, -3.29),
    'nordic-writing': (-2.22, -4.91, -5.63, -0.46),
    'cyrillic-skr': (-1.03, -0.76, -0.08, -0.13),
    'cyrillic-script': (0.0, -5.96, -3.97, -0.03),
    'english-writing': (-0.01, -1.36, -0.40, -0.06),
    'cri-syllable': (-1.65, -0.38, -0.06, 0.0),
}


def response(previous, token):
    s = token.strip().lower()
    match = re.search(r'[^\W\d_]+$', previous + token)
    original = match.group().lower() if match else ''
    word = ''.join(c for c in unicodedata.normalize('NFD', original)
                   if not unicodedata.combining(c)).replace('ſ', 's')
    joined = bool(previous and previous[-1:].isalpha()
                  and token[:1].isalpha())
    if s in WRITE_FORMS:
        if joined and re.search(r'(screen|hand|under|copy|play|ghost)$',
                                previous, re.I):
            form = 'writer' if s.startswith('writer') else s
            return COMPOUNDS.get(form, 0.0)
        return WRITE_FORMS[s]
    if 'transcript' in s:
        return (-6.41 if 'transcription' in s else
                -1.65 if s.endswith('s') else -3.32)
    if s == 'subscript':
        return -5.66
    if 'prescription' in s:
        return -5.10
    if 'prescrib' in s:
        return -2.16
    if 'subscrib' in s:
        if s.startswith('un'):
            return -1.74
        return -1.24 if s.endswith(('r', 'rs')) else -4.12
    if 'subscription' in s:
        return -1.61 if s.endswith('s') else -2.76
    if 'typescript' in s:
        return -0.59
    if 'javascript' in s:
        return -0.03
    if s in ('scribe', 'scribes', 'scribed', 'scribing', 'scription'):
        return -3.65
    if s in SCRIPT_FORMS:
        return SCRIPT_FORMS[s]
    if re.search(r'(manu|in|con|post)script', s):
        return -0.23
    if re.match(r'describ|descript|manuscript|inscription', s):
        return 0.0
    if joined and 'screen' in (previous + token).lower()[-25:] and \
            re.search(r'(play(?:s|ed)?|writer)$', word):
        return -8.10 if 'play' in s else -4.32
    if any(c in token for c in '写寫'):
        return -0.54
    if joined and word.endswith('脚本'):
        return -5.51
    if joined and re.fullmatch(r'crat(?:e|es|er|ers)', word):
        return 2.15
    if joined and original.endswith(('스크립', '스크립트')):
        return -7.50
    if joined and original.endswith(('スクリ', 'スクリプ', 'スクリプト')):
        return -4.46
    if joined and word.endswith(('转录', '轉錄')):
        return -8.12

    root = re.search(r'schr|scr|skr|ecr|скр|wr|cri|kri|кри', word)
    if not root:
        return 0.0
    cluster, rest = root.group(), word[root.end():]
    if not joined:
        return -0.63 if rest in ('', 'i') else 0.0
    if len(rest) > 9:
        return 0.0
    if cluster == 'schr':
        family = ('german-script' if rest.startswith('if') else
                  'german-writing' if rest.startswith(('ei', 'ie', 'ij', 'ee'))
                  else 'german-cluster')
    elif cluster == 'wr':
        family = 'english-writing'
    elif cluster in ('cri', 'kri', 'кри'):
        family = 'cri-syllable'
    elif cluster == 'скр':
        family = 'cyrillic-script' if rest.startswith('и') else 'cyrillic-skr'
    elif cluster == 'skr':
        if rest and not rest.startswith(('i', 'ev')):
            return 0.0
        family = 'nordic-writing'
    else:
        if rest and not rest.startswith('i'):
            return 0.0
        family = ('prefixed-scribere' if
                  re.search(r'(pre|tran|con|sub)$', word[:root.start()])
                  else 'romance-writing')
    # Endings well past the syllable are weaker, except in German Schrift.
    if len(word) - len(token) > root.end() + 2 and family != 'german-script':
        return ROOTS[family][3]
    if 2 < len(rest) <= 3 and family == 'german-writing':
        return -5.37
    stage = (0 if not rest else 1 if len(rest) <= 2 else
             2 if len(rest) <= 5 else 3)
    return ROOTS[family][stage]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    old = previous.decode('utf-8', errors='ignore')
    token = (previous + raw).decode('utf-8', errors='ignore')[len(old):]
    return (doc, (previous + raw)[-80:]), response(old, token)

"""A sparse spelling-based approximation, not a semantic classifier.

Its main response is negative on Japanese na, ne and yo fragments.  For
standalone na, short preceding fragments produce the strongest response.
A second response follows three liáng spellings and Latin iang/li+ang.
Vietnamese đ+ón is positive. Two document-opening patterns (a comment
marker and the digits 12) have separate rules. Everything else scores zero.
Only the previous token and document position are remembered.
"""
import regex

READS = ()


def predict(s, previous, position):
    if s == "な":
        if not previous:
            return -3.0
        last = previous[-1]
        short = len(previous) <= 2
        if regex.fullmatch(r"\p{Script=Hiragana}", last):
            return -6.5 if short else -4.7
        if regex.fullmatch(r"\p{Script=Han}", last):
            return -3.6 if len(previous) == 1 else -2.6
        if regex.fullmatch(r"\p{Script=Katakana}", last):
            return -4.5 if short else -2.4
        return -5.7 if len(previous) == 1 else -2.0
    if s == "なり":
        return -4.4
    if s == "ね":
        return -2.05
    if s == "よ":
        return -3.13
    if s == "ら":
        return -0.82
    if len(s) == 2 and s.endswith("な"):
        if regex.fullmatch(r"\p{Script=Hiragana}+", s):
            return -1.4
    if s == "なる":
        return -1.9
    if s.startswith("なら") and len(s) <= 4:
        return -0.8
    if s in ("なん", "なんだ"):
        return -1.6
    if s == "なぁ":
        return -2.3

    # Three liáng spellings: good, beam, and sorghum.  This is not a
    # rule for all Mandarin liáng homophones (e.g. 凉 is not included).
    if s == "良":
        return -5.2
    if s in ("梁", "粱"):
        return -8.5
    if s == "iang":
        return -5.5 if previous.lower().endswith("ch") else -1.8
    if s == "ang" and previous.lower().endswith("li"):
        return -6.4
    if s == "ón" and previous.endswith("đ"):
        return 10.5

    if position == 0 and s == "//\n":
        return -6.5
    if position == 1 and previous == "1" and s == "2":
        return -2.63
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ""
    else:
        _, position, previous = carry
    s = prefix.token_strings[-1]
    value = predict(s, previous, position)
    return (doc, position + 1, s), value

"""A causal approximation for date prefixes and indentation.

Give a negative pulse on the second digit of ASCII 19... or 20...;
date words, months, citations and Chinese context strengthen the pulse.
Chinese 一九/二零 have analogous pulses. Later 19/20 pairs inside a longer
number instead get small positive values.

Spaces immediately after a newline get a stronger negative response near
the document's start, especially short even-width runs. Small extra rules
cover tabs, middle-dot separators, document-opening package/using keywords,
and initial space tokens one character shorter than a multiple of four.
Other positions get zero: smaller lexical fluctuations are not modeled.
"""
import calendar
import math
import re
import regex

READS = ()
MONTHS = {s.lower() for s in calendar.month_name if s}
TEMPORAL = {
    'in', 'since', 'during', 'before', 'after', 'until', 'from', 'between',
    'year', 'years', 'born', 'died', 'copyright', 'circa', 'published',
    'released', 'dated', 'established', 'founded', 'early', 'late', 'the',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0)
    _, digits, previous, text, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if token.isdecimal():
        pair = digits + token
        if pair in ('19', '20'):
            value = -0.38 if pair == '19' else -0.17
            before = text[:-len(digits)]
            words = re.findall('[A-Za-z]+', before[-60:])
            word = words[-1].lower() if words else ''
            if before.endswith(' '):
                value -= 0.17
            if before.endswith(' ('):
                value -= 0.47
            if word in TEMPORAL:
                value -= 0.49
            if word in MONTHS:
                value -= 0.36
            if re.search(r'\bet\s+al[.,()\s]*$', before, re.I):
                value -= 0.72
            last = before.rstrip()[-1:]
            if regex.fullmatch(r'\p{Script=Han}', last):
                value -= 0.44
            if last in ('在', '于', '於', '年'):
                value -= 0.53
        elif digits.endswith('2') and token == '0':
            value = 0.27
        elif digits.endswith('1') and token == '9':
            value = 0.06
        digits = (digits + token)[-16:]
    else:
        digits = ''
    if token.startswith('九') and text.endswith('一'):
        value = -1.28
    if token.startswith('零') and text.endswith('二'):
        value = -1.6
    if token and not token.strip(' ') and previous.endswith('\n'):
        early = math.exp(-position / 20)
        value = 0.04 - 0.66 * early
        if len(token) <= 12 and len(token) % 2 == 0:
            value = -0.06 - 1.2 * early
            if len(token) in (4, 8):
                value -= 0.2
    if token == '\t':
        value = 0.08
    if len(token) >= 2 and not token.strip('·'):
        value = -1.46
    if position == 0:
        if token in ('package', 'using'):
            value = 3.35
        if token and not token.strip(' ') and len(token) >= 3:
            if len(token) % 4 == 3:
                value = 2.0
    return (doc, digits, token, (text + token)[-120:], position + 1), value

"""Approximate a document-opening transient, not a topic detector.

The signal is usually tiny after the opening token changes. Repetitions of
that token retain its opening value. Amplitudes depend on spelling: English
commonness, capitalization, leading space, and punctuation. A few recognizable
openers have unusually large values: Q, chat boundaries, caret/dot dividers,
and the colon completing an initial 'Title:'. These rules leave fine-grained
lexical differences and most small, later activations unexplained.
"""
from wordfreq import zipf_frequency
import regex

READS = ()


def opening(token):
    text = token.strip()
    spaced = token[:1].isspace()
    if token == '<|im_start|>':
        return 3.056
    if token == 'Q':
        return -8.026
    if token == 'Title':
        return 0.272
    if len(text) > 1 and set(text) == {'^'}:
        return min(15.4, len(text) ** 2 - 0.7)
    if len(text) > 1 and set(text) == {'·'}:
        return 10.28
    if '\\' in token:
        return 4.87
    if not spaced and text.lstrip('#').lower() in {'include', 'import'}:
        return 6.8 if text.startswith('#') else 4.3
    if not text:
        return -1.47 if '\n' in token else -0.35
    if text.isdigit():
        return -0.75
    if '\ufffd' in text:
        return 1.96
    if any(c.isalpha() for c in text):
        if not text.isascii():
            return 2.8 if regex.search(r'\p{Script=Cyrillic}', text) else 1.5
        frequency = zipf_frequency(text.lower(), 'en')
        if spaced:
            if frequency > 7.5:
                return -2.05
            if frequency > 6.3:
                return -0.86
            return -0.58 if len(text) > 6 else 0.14
        if frequency > 6.36:
            return 0.15
        if text[0].isupper():
            if text.isupper():
                return 1.5
            return 4.4 if frequency < 3.3 else 2.68
        return -1.59 if len(text) > 6 and frequency > 4.45 else 1.4
    if not spaced and text.startswith('#'):
        return -2.61 if len(text) == 1 else 0.52
    return -0.32


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        value = opening(token)
        return (token_id, token, value, True, 0), value
    initial_id, initial_text, initial_value, repeating, age = carry
    age += 1
    repeating = repeating and token_id == initial_id
    if repeating:
        value = initial_value
    elif age == 1 and initial_text == 'Title' and token == ':':
        value = 15.472
    else:
        value = 0.002
    return (initial_id, initial_text, initial_value, repeating, age), value

"""Approximate negative response to the spelling 'ie' in short fragments.

Recognize ie within a token, i/e across adjacent tokens, and an immediately
following word fragment. Token lengths and spaces distinguish fragments from
longer whole-looking words. For initial-ie fragments, the common endings
-ien/-ier/-ies are weaker than other consonant continuations. Short Cyrillic
cross-boundary matches are weaker too. Romanize non-Han text, retaining just
one previous token and resetting it at document boundaries.

This captures a shared spelling pattern, not finer word-specific amplitudes.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()
# Leave out n/r/s to distinguish the common -ien/-ier/-ies endings.
CLOSING_CONSONANTS = frozenset('bcdfghjklmpqtvwxz')

@lru_cache(maxsize=32768)
def spelling(text):
    if regex.search(r'\p{Script=Han}', text):
        return text.lower()
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_bytes[-1].decode('utf-8', 'replace')
    current = spelling(text)
    word, before = current.strip(), previous.strip()
    value = -0.002

    if 'ie' in word:
        if word.startswith('ie'):
            following = word[2:3]
            if following in CLOSING_CONSONANTS:
                value = -3.07 if len(before) <= 2 else -1.56
            elif len(word) == 2:
                value = -1.54 if len(before) <= 2 else -0.73
            else:
                value = -0.32
        else:
            value = -0.36 if len(word) <= 4 else -0.05

    elif word.startswith('e') and previous.rstrip().endswith('i'):
        if current[:1].isspace():
            value = -0.01
        else:
