лер/лар, and double middle dots. Bare plural fragments at document starts get
a default negative response. Other text gets zero. This is not a complete
morphological parser and omits idiosyncratic word-specific responses.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
WORDS = re.compile(r"[^\W\d_]+(?:['’][^\W\d_]+)*")
# Plurals merged with a stem vowel; non-harmonic a+ler is much weaker.
TR_PLURALS = {
    'alar': -8.2, 'lar': -5.8, 'iler': -6.0, 'ular': -6.0,
    'üler': -3.0, 'olar': -3.0, 'aler': -0.3,
}
RO_ENDINGS = {
    'ul': -4.2, 'ului': -3.8, 'le': -5.3, 'ile': -5.4,
    'ele': -5.3, 'elor': -5.7, 'ilor': -4.6, 'lor': -5.8,
    'iei': -3.1, 'ii': -2.2, 'uri': -3.0, 'ei': -4.0,
}


@lru_cache(maxsize=24000)
def language_clue(word):
    """A word counts only if it is distinctly more frequent in one language."""
    tr = zipf_frequency(word, 'tr')
    ro = zipf_frequency(word, 'ro')
    competitors = ('en', 'de', 'fr', 'it', 'es', 'pt', 'sv', 'da', 'nl', 'hu')
    other = max(zipf_frequency(word, lang) for lang in competitors)
    return (tr >= 3 and tr > max(ro, other) + 0.7,
            ro >= 3 and ro > max(tr, other) + 0.7)


