                or s in ('i', 'or', 'ui', 'ı', 'lik', 'lık', 'isi', 'ası', 'li')
                or len(s) <= 4 and (s.endswith('l') or s.startswith(('ar', 'er')))
                or re.fullmatch('l[ae]r[ıi].*|l[ae]rd', s))
