        value = RO_ENDINGS.get(s, value)
        if previous.endswith('l') and s in ('or', 'ui'):
            value = -6.5 if s == 'or' else -4.3
        if s == 'i':
            value = -3.0 if previous.endswith(('e', 'i')) else -0.35
    return state, value

