SUBJECT = {
    'i': (10.3, 7.9), 'you': (5.8, 7.0), 'we': (4.2, 3.9),
    'they': (5.2, 5.0), 'he': (6.8, 7.0), 'she': (6.8, 7.0),
}
ABILITY = {'can', 'cannot', 'could'}
QUESTION = ABILITY | {'do', 'does', 'did', 'help', 'helps', 'helping'}
FUTURE = {'will', 'would', 'may', 'might', 'shall', "'ll", '’ll'}
REACTION = {'happy', 'glad', 'surprised', 'startled', 'likely',
           'anxious', 'unusual', 'pleased', 'delighted'}
