PAST_CONTEXT = {
    'be': 1.2, 'is': 2.2, 'am': 2.2, 'are': 2.2,
    'was': 2.7, 'were': 2.7, 'been': 3.1,
    'have': 4.8, 'has': 4.8, 'had': 4.8, "'ve": 4.8, '’ve': 4.8,
    'not': 2.3, "'t": 2.3, '’t': 2.3, 'and': 5.5, 'also': 5.5,
}
FORMS = {
    'findings': 1.8, 'finder': 5.8, 'finders': 7.0,
    'finde': 4.0, 'finden': 3.8, 'findet': 4.2,
    'founded': 1.5, 'founding': 1.6, 'founder': 1.8,
    'foundation': 0.5, 'foundations': 0.2,
    'funds': 0.8, 'funded': 0.5, 'funding': 0.4, 'refund': 2.6,
    'vind': 2.6, 'fruit': -0.7, 'fruits': -1.8,
    'fur': -1.5, 'furry': -1.5, 'furn': -1.0,
    'fut': -0.6, 'furt': -1.6, 'gefunden': 0.7,
    '发现': 0.9, '發現': 0.9, '找到': 0.4,
}


def response(s, history, word):
    t = s.strip().lower()
    p = history[-1].strip().lower() if history else ''
    q = history[-2].strip().lower() if len(history) > 1 else ''
    if t in {'find', 'found'}:
        past = t == 'found'
        if not past and s.strip() != 'find':
            return 0.5  # Often an imperative or a menu label.
        if p in SUBJECT:
            if not past and q in QUESTION:
                return 1.0
            if not past and q in {'if', 'when', 'once', 'until', 'suppose'}:
                return 5.8
            return SUBJECT[p][int(past)]
        if past:
            return PAST_CONTEXT.get(p, 3.2)
        if p == 'to':
            return 4.5 if q in REACTION else 0.7
        if p in ABILITY or (p in {'not', "'t", '’t'} and q in ABILITY):
            return 1.3
        if p in FUTURE:
            return 6.6
        if p in {'and', 'also', 'not', "'t", '’t', 'did'}:
            return 4.5
        if p in {',', 'then', '=', 'const', 'help', 'me', 'us'}:
            return 1.1
        return 3.0
    if t == 'finds':
        return 2.7 if p in {'it', 'that'} else 6.5
    if t == 'finding':
        if p in {'of', 'for', 'about', 'by', 'on', 'to'}:
            return 0.9
        return 6.4 if p in {"'s", '’s', "'re", '’re'} else 3.2
    if t == 'fund':
        if p in {'de', 'su', 'una', 'ao', 'foi', 'die'}:
            return 7.0
        return 0.6 if p == 'to' else 2.5
    if t.startswith('fond'):
        return 6.2
    if t.startswith('trouv'):
        return 1.3
    if t and set(t) == {'·'} and '·' in p:
        return 1.1
