    if s and s[0].isalpha() and word:
        joined = word + t
        if s[0].islower():
            if word.endswith(('fond', 'fund')) and t in {'o', 'os', 's', 'i'}:
                return 8.5
            if word.endswith('find') and t in {'er', 'ers', 'en', 'et', 'ing', 'ings'}:
                if word.endswith('befind'):
                    return 1.2
                return 2.0 if t in {'ing', 'ings'} else 5.8
