            return any(m.start() < len(word) < m.end()
                       for m in re.finditer(pattern, joined))
        if crosses(r'f(?:[iaouü]|ou)nd'):
            return 6.6 if len(word) <= 2 and word.endswith('f') else 4.3
        if 'frank' in word and t in {'fur', 'fort'}:
            return -6.0
        if crosses(r'frut'):
            return -4.0
        if crosses(r'f(?:ru|ur)'):
            return -2.0
        if crosses(r'fut'):
            return -2.9
    return FORMS.get(t, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history, word, last = (), '', 0.0
    if carry is not None and carry[0] == doc:
        _, history, word, last = carry
    s = prefix.token_strings[-1]
    value = response(s, history, word)
    t = s.strip().lower()
    if history and history[-1].strip().lower() in {'find', 'found', 'finds'}:
        if t == 'it':
            value += 0.67 * last
        elif t == 'this':
            value += 0.24 * last
        elif t == 'yourself':
            value += 0.12 * last
    text = word + s if s and s[0].isalpha() else s
    match = re.search(r'[^\W\d_]+$', text.lower())
    word = match.group()[-32:] if match else ''
    return (doc, (history + (s,))[-2:], word, value), float(value)

