"""Component layers.1.mlp.down_proj:5662: the English verb "find" / "found".

A spelling detector. It fires on the token that spells out "find", "finds",
"finding", "found", "finder", "fund", "fond" (and "refund", "founder", "founded",
German "fand"/"finden"/"findet") and is silent on almost everything else. It does
not respond to synonyms (discover, locate) or to longer words that merely contain
them (foundation, funding).

How strongly it fires depends on the word just before it:
- a subject pronoun or a modal ("I found", "we find", "you will find"): strong;
- "and", "also", "have", "been", "who", "just" before it: fairly strong;
- "to", "be", "cannot", a full stop, a colon, a quote, "=", "#", an opening
  bracket (infinitives, passives, imperatives, code): weak;
- anything else: medium.

It keeps only the previous token, so it has no carry, and it treats a new
document as having no previous word.
"""

READS = ()

FIND_WORDS = {
    "find", "finds", "finding", "findings", "finder", "found", "fund", "funds",
    "fond", "fondo", "refund", "founded", "founder", "finden", "findet", "finde", "fand",
}
PRONOUNS_AND_MODALS = {"i", "we", "you", "he", "she", "they", "will", "'ll"}
FLUENT_BEFORE = {"and", "also", "have", "has", "had", "been", "who", "just"}
WEAK_BEFORE = {
    "to", "be", "cannot", "the", ".", '"', ":", "=", "#", "(", "for", "then", "of", "",
}
STRONG, FAIRLY_STRONG, MEDIUM, WEAK = 6.0, 4.5, 3.0, 1.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in FIND_WORDS:
        return None, 0.0
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, MEDIUM
    before = prefix.token_strings[-2].strip().lower()
    if before in PRONOUNS_AND_MODALS:
        return None, STRONG
    if before in FLUENT_BEFORE:
        return None, FAIRLY_STRONG
    if before in WEAK_BEFORE:
        return None, WEAK
    return None, MEDIUM

"""Layer-1 MLP component 5663: a document-opening detector.

Its activation is almost zero everywhere except at the first few tokens of a
document (positions where the model sees no earlier text of that document),
plus a handful of special token patterns. Predicted values, in the same units
as the component's activation:

  * a document that opens with a carriage-return line ending (a token containing
    a carriage return, e.g. CRLF, ' {\\r\\n', ');\\r\\n'): about +12, and a bare
    comment marker line ('#\\n', '//\\n'), or a run of carriage returns at the
    very start: very large;
  * a document that opens with '<|endoftext|>' (+12), or a YAML '---' line (+5);
  * the middle-dot leader token '··' anywhere (+3.7);
  * '^^^^' in the first two tokens (+11), and a '2' right after a document-initial '1' (+15).

Everything else is 0. Most ordinary text is ~0; the variance of the document
start tokens that are not listed here is left unexplained.
"""

READS = ()

COMMENT_LINE = ("#\n", "//\n", "#\r\n", "//\r\n", " #\r\n", " //\r\n", "///\r\n", "///\n")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    cur = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        dpos, only_cr, prev = 0, True, None
    else:
        dpos, only_cr, prev = carry[1] + 1, carry[2], carry[3]
    only_cr = only_cr and cur == "\r"
    carry = (doc, dpos, only_cr, cur)
    if dpos == 0:
        if cur in COMMENT_LINE:
            return carry, 120.0
        if "\r" in cur:
            return carry, 12.0
        if cur == "<|endoftext|>":
            return carry, 11.7
        if cur == "---\n":
            return carry, 5.0
    if cur == "\r" and only_cr and dpos <= 4:
        return carry, 162.0
    if cur == "··":
        return carry, 3.66
    if cur == "^^^^" and dpos <= 2:
        return carry, 11.2
    if cur == "2" and dpos == 1 and prev == "1":
        return carry, 14.7
    if cur == "<|endoftext|>" and dpos == 1:
        return carry, 5.0
    return carry, 0.0

