                value += 0.082 * echo
            elif plain in {'-', '−', '–'}:
                value += 0.214 * echo
        echo_age = 2 if plain else echo_age + 1
    if s.strip() == '+' and previous.rstrip().endswith(('"', "'")):
        value += 0.660  # string concatenation
    value += word_value(s, previous)
    # A row consisting solely of middle-dot ornamentation is a distinct case.
    dots_only = dots_only and s == '··'
    if dots_only:
        value += 0.910
    line = (line + s).split('\n')[-1][-160:]
    return (doc, stack, echo, echo_age, s, dots_only, line), float(value)

"""A sparse local spelling signal around c/C.

Short fragments with repeated c's, including abbreviations, are negative.
Fragments spelling codec, and short c-starting fragments after code,
are stronger; c joined to ay/uy is also negative.
Joining c to uncommon ch/cl fragments, or cr/cl to am/um, is positive.
This is a coarse spelling rule, not a model of every lexical exception.
"""

from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def common_word(text):
    return zipf_frequency(text, 'en') >= 4.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    q = token.lower().strip()
    p = previous.lower().strip()
    # ch and ck are single consonant spellings, not repeated c's.
    current = q.replace('ch', 'h').replace('ck', 'k')
    before = p.replace('ch', 'h').replace('ck', 'k')
    positions = [i for i, ch in enumerate(current) if ch == 'c']
    letters = sum(ch.isalpha() for ch in current)
    joined = bool(previous) and previous[-1].isalpha() and token.isalpha()
    value = 0.0

    if len(positions) >= 2:
        distance = positions[-1] - positions[0]
        if distance >= 2 and letters <= 3:
            value = -3.8
        elif distance >= 2 and letters <= 5 and current.endswith('c'):
            value = -0.4

    if joined and positions and 'c' in before:
        gap = len(before) - before.rfind('c') + positions[0]
        length = len(previous) + len(token)
        if gap <= 7:
            if length <= 5:
                if current.endswith('c'):
                    value = -3.6 if gap <= 2 else -1.6
                else:
                    value = -0.4
            elif len(token) <= 3:
                value = -0.7 if gap <= 4 else -0.2

    if joined and p.endswith('c'):
        if q.startswith(('ay', 'uy')) and len(p) <= 2:
            value = -2.5
        if ('ch' in q or q.startswith('cl')) and len(q) <= 5:
            if len(q) <= 2 or not common_word(q):
                value = 0.75
    if joined and p.endswith(('cr', 'cl')) and q.startswith(('am', 'um')):
        value = 0.85

    # Code followed by another c is an unusually strong spelling pattern.
    if q.startswith('codec'):
        value = -7.2 if joined else -4.8
    elif joined and p.endswith('code'):
        if q in ('c', 'cs'):
            value = -4.5 if token.isupper() else -8.5
        elif q.startswith('c') and len(q) <= 3:
            value = -3.6

    return (doc, token), value

"""Padding boundaries and console-output syntax, with a few lexical side responses.

Positive responses mark single spaces after padding, printing/output APIs, main
entry points, and promise `.then`. Padding responses are larger near document start.
Indented loops and among/amongst are negative; among is stronger after a relational
noun (WordNet). This is a local approximation, not a parser or execution model.
"""
import wordnet

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2]
    doc = prefix.document_ids[-1]
    pos = carry[1] + 1 if carry and carry[0] == doc else 0
    return (doc, pos), activation(token, previous, pos)


def activation(token, previous, position=512):
    word, prev = token.strip(), previous.strip()
    padding = bool(previous) and previous.isspace() and '\n' not in previous
    newline = '\n' in previous or previous.endswith('\\n')
    statement = (padding or newline or token.startswith('\t') or
                 previous.rstrip().endswith(('#', ';', '`')))

    if token == ' ':
        if previous and set(previous) <= {' ', '\t'}:
            n = len(previous)
            base = 0.25 if n == 1 else 1.05
            if n >= 4:
                base = 1.2 if n == 4 else 0.94
            if position < 3:
                boost = 0.6
            elif position < 16:
                boost = 0.3
            else:
                boost = 0.15 if position < 64 else 0.0
            return base + boost
        return -0.01
    if word == '.log':
        return 3.3 if prev.lower() == 'console' else 0.09
    if word == '.out':
        return 2.65 if prev == 'System' else 1.1
    if word == '.Printf':
        return 1.45
    if word in {'.Println', '.WriteLine'}:
        return 2.0
    if word == '.println':
        return 1.65
    if word == '<<':
        return 1.3 if prev.endswith('cout') else 0.15
    if word == '.show' and prev == 'plt':
        return 1.35
    if word == 'alert':
        return 1.3 if statement else 0.3
    if word == '_dump' and prev == 'var':
        return 2.0
    if word in {'print', 'printf', 'println'}:
        if token.startswith('\t') and word == 'printf':
            return 1.4
        return 2.05 if statement else 0.4
    if word == 'cout':
        return 1.94
    if word.lstrip('"') == 'fmt':
        return 1.4
    if word in {'console', 'Console'}:
        if statement:
            return 1.7 if word == 'Console' else 0.9
        return 0.25
    if word in {'stdio', 'iostream', '<iostream'}:
        return 2.5
    if word == 'echo':
        return 0.62 if token.startswith('\t') else 1.2 if statement else 0.36
    if word in {'main', 'Main'} and prev in {'int', 'void'}:
        return 2.85
    if word == 'main':
        return 1.7 if prev in {'func', 'fn'} else 0.18
    if word.lower() == 'then':
        if token == 'then' and previous.endswith('.'):
            return 5.65
        return 0.22
    if word in {'for', 'while', 'foreach'}:
        if padding or token.startswith('\t'):
            return -0.86
        if newline and token == word:
            return -0.54
    if word.lower() in {'among', 'amongst'}:
        if not word.islower():
            return -0.59
        for base in wordnet.base_forms(prev.lower()):
            if 'noun.relation' in wordnet.categories(base):
                return -2.45
        return -1.1
