        return 0.33
    return 0.0

"""Local spelling fragments and 'of' constructions.

The spelling rule distinguishes short continuations after st, with positive
responses to vowel digraphs and selected stems, and negative responses to
other selected stems. It is deliberately tokenization-sensitive, not a
semantic category. There are also whole-token stain/stew/stake rules.
Unmatched positions return zero; document boundaries cut off context.
"""
import re

READS = ()


def continuation(previous, word):
    if word.startswith('air'):
        return 7.4
    if word.startswith('ain'):
        return 2.0 if word.startswith('aining') else 4.6
    if word.startswith('ew'):
        return 4.7
    if word.startswith('reak'):
        return 8.5
    # Short vowel digraphs, not longer grammatical endings such as -ion.
    if re.fullmatch(r'[aeiou][aeiouwy]', word):
        return 2.0
    if word.startswith(('ok', 'ink')):
        return 2.6
    if word in ('ur', 'ura', 'ac'):
        return 2.6 if sum(c.isalpha() for c in previous) <= 3 else 0.0
    if word in ('ak', 'aks', 'ake', 'akes'):
        return 1.8
    if word in ('att', 'ore'):
        return -4.5
    if word.startswith('ack'):
        return -5.5
    if re.fullmatch(r'at(?:e[ds]?|ors?|o|t)?', word):
        return -2.5
    if word.startswith(('yl', 'aff', 'uff')):
        return -2.5
    if word.startswith(('or', 'ar', 'ill', 'ress')):
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = ''
    if len(prefix.token_ids) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
    before = previous.strip()

    if word == 'of':
        if before.lower() == 'most':
            if (len(prefix.token_ids) > 2
                    and prefix.document_ids[-3] == prefix.document_ids[-1]
                    and prefix.token_strings[-3].strip().lower() == 'the'):
                return None, -1.0 if before[:1].isupper() else 0.2
            return None, -5.8 if before[:1].isupper() else -4.7
        if before.lower() == 'instead':
            return None, -3.8
        if before.lower() == 'plenty':
            return None, -2.2 if before.islower() else -1.0
        if before.lower() == 'lots':
            return None, -1.8
        if before.lower() == 'lot':
            return None, -0.95

    continues = token[:1].isalpha() and not (
        token[:1].isupper() and previous[-1:].islower())
    if previous.lower().endswith('st') and continues:
        return None, continuation(previous, word)
    if previous.lower().endswith('ст') and continues:
        if word.startswith('ат'):
            return None, -3.5 / (1 + max(0, len(word) - 2))
        if word.startswith(('ав', 'ор', 'ит')):
            return None, -1.2 / (1 + max(0, len(word) - 2))

    if re.fullmatch(r'stain(?:s|ed|ing)?', word):
        return None, max(1.0, 5.1 - 0.75 * (len(word) - 5))
    if word.startswith('stew'):
        return None, 4.8
    if word.startswith('stake'):
        return None, 2.0
    if word == 'statt' and (token[:1].isspace() or not previous[-1:].isalpha()
                           or before.lower() == 'an'):
        return None, -3.8
    if token == previous == '··':
        return None, 1.73
    return None, 0.0

programs.haiku:
"""Layer-1 MLP feature 5669 (down_proj), explained as two word-level rules.

1. Partitive "of" after a quantity word: the component goes strongly negative on " of" in
   "most of the", "instead of", "plenty of", "lots of", "a lot of". Size follows how
   strongly the word takes "of": "most" and "instead" give the largest negative values,
   "lot" the smallest.
2. Words beginning with the stems "stai-", "stak-", "stew-", "stua-" (stair, stain, stake,
   stew, Stuart and similar) make it positive, about +2, on the word's later pieces.

Everywhere else the component is near zero, so the program predicts 0 there.
"""

READS = ()

QUANTITY_OF = {"most": -4.7, "instead": -3.9, "plenty": -2.1, "lots": -1.8, "lot": -1.0}
ST_STEMS = ("stai", "stak", "stew", "stua")


def current_word(strings):
    """The letters of the word the newest token belongs to (its earlier pieces included)."""
    word = ""
    for s in reversed(strings):
        letters = s.lstrip(" ")
        if not letters.isalpha():
            break
        word = letters + word
        if s.startswith(" "):
            break
    return word


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    if len(strings) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    if strings[-1].strip() == "of":
        return None, QUANTITY_OF.get(strings[-2].strip().lower(), 0.0)
    word = current_word(strings).lower()
    if len(word) >= 5 and word.startswith(ST_STEMS):
        return None, 2.0
    return None, 0.0

programs.sol:
"""A weak geographical-word signal, with separate document-start behavior.

Title-case country and European/Asian inhabitant words are positive,
particularly European countries and Turkish places. Government words and mixed tab/space indentation are
negative. A small template rule recognizes the phrase 'Challenge Level'.
At document starts, function-declaration keywords can be strongly positive;
other first tokens use coarse script and formatting rules.
"""
from functools import lru_cache
from anyascii import anyascii
import pycountry
import regex
import wordnet

READS = ()
C_SCALAR_TYPES = {'bool', 'char', 'short', 'int', 'long', 'float', 'double'}
FUNCTION_WORDS = {'def', 'function'}
DECLARATION_MODIFIERS = {'public', 'private', 'static'}
# European countries outside Britain/Ireland, including transcontinental ones.
EUROPE = set('''
AL AD AT BY BE BA BG HR CY CZ DK EE FI FR DE GR HU IS IT
LV LI LT LU MK MD MC ME MT NL NO PL PT RO RU SM RS SK SI ES
SE CH TR UA VA
'''.split())
COUNTRIES = {}
for country in pycountry.countries:
    for field in ('name', 'common_name', 'official_name'):
        if hasattr(country, field):
            COUNTRIES[getattr(country, field).lower()] = country.alpha_2
COUNTRIES.update(russia='RU', turkey='TR', korea='KR')
TURKISH = {'turkey', 'turkish', 'turkiye'}
TURKISH.update(anyascii(p.name).lower()
               for p in pycountry.subdivisions.get(country_code='TR'))


@lru_cache(maxsize=32768)
def lexical(token):
    word = token.strip()
    lower = word.lower()
    value = 0.002
    if '\t' in token and ' ' in token and not word:
        return -0.122
    if not word.isalpha():
        return value
    if word.istitle():
        country = COUNTRIES.get(lower)
        if anyascii(lower) in TURKISH:
            # Avoid ordinary English senses of province names, e.g. 'Van'.
            senses = wordnet.categories(word)
            if (country == 'TR' or lower == 'turkish'
                    or not senses or 'noun.location' in senses):
                return 0.53
        if country:
            value += 0.09
            if country in EUROPE:
                value += 0.205
        if wordnet.is_a(word, 'European') or wordnet.is_a(word, 'Asian'):
            value += 0.11
        if wordnet.is_a(word, 'city'):
            value += 0.033
        if wordnet.is_a(word, 'continent'):
            value += 0.075
    if lower in {'country', 'countries'}:
        value += 0.088
    if wordnet.is_a(word, 'village'):
        value += 0.092
    if token.startswith(' ') and wordnet.is_a(word, 'government'):
        value -= 0.043
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry != doc:
        word = token.strip()
        value = -0.097 - 0.262 * word.isdigit()
        value += 0.287 * ('>' in token) - 0.208 * ('\n' in token)
        value += 0.170 * bool(regex.search(r'\p{Script=Han}', word))
        value += 0.063 * word.istitle()
        # Bare keywords, not space-prefixed words partway through source.
        if token == 'void':
            value = 2.13
        elif token in C_SCALAR_TYPES:
            value = 0.75
        elif token in FUNCTION_WORDS:
            value = 1.15
        elif token in DECLARATION_MODIFIERS:
            value = 1.44
    elif (token.strip() == 'Level' and prefix.position > 0
          and prefix.token_strings[-2].strip() == 'Challenge'):
        value = 0.14
    else:
        value = lexical(token)
    return doc, float(value)

programs.haiku:
"""Document-opening tokens only.

The component reads the first token of each document (the token right after a
document break, where attention can see nothing but itself). Its output there is
set by which kind of token it is:

- code or markup openers (def, export, #, //, quotes, tabs, braces, ...): strongly positive
- digits and symbols such as $ = | & < : negative
- Chinese/Japanese/Korean characters and other non-letter openers: small
- ordinary words: slightly negative

Everywhere else (every token inside a document) it predicts 0.
"""
READS = ()

CODE_WORDS = {"def", "import", "export", "package", "using", "int", "class", "const",
              "function", "var", "return", "public", "static", "void"}
CODE_OPENERS = ("#", "//", "/*", '"', "“", "\t", "{", "---", "__", "\\\"", "[")
SYMBOLS = set("$=|&^`<")
VALUES = {"code": 0.7, "digit": -0.28, "symbol": -0.3, "cjk": 0.1, "other": 0.05, "word": -0.07}


def starts_document(prefix):
    return prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]


def kind(text):
    t = text.strip()
    if t in CODE_WORDS or t.startswith(CODE_OPENERS):
        return "code"
    if t[:1].isdigit():
        return "digit"
    if t[:1] in SYMBOLS:
        return "symbol"
    if "一" <= t[:1] <= "鿿":
        return "cjk"
    if t[:1].isalpha() or t == "":
        return "word"
    return "other"


def step(carry, prefix, upstream):
    if not starts_document(prefix):
        return carry, 0.0
    return carry, VALUES[kind(prefix.token_strings[-1])]

programs.sol:
"""Local difficulty/help constructions and temporal action clauses.

Strong responses mark 'have trouble', 'need help' and 'hard time'.
Definite references like 'the problem' are weaker. Additional rules cover
feelings, inability, and prepositions continuing these constructions.
Only the current token and 120 preceding characters are used. This omits
lexical idiosyncrasies and longer-context variation. Constants were fitted
on training text. Secondary rules cover document starts, Portuguese 'ao',
and repeated middle-dot leaders.
"""
import re

READS = ()
ADVERSITY = set("""
problem problems issue issues trouble troubles difficulty difficulties
error errors mistake mistakes challenge challenges confusion inconsistency
inconsistencies uncertainty uncertainties
""".split())
DIFFICULTY = set("difficulty difficulties trouble troubles".split())
FEELINGS = set("comfortable uncomfortable confused stuck unsure horrible".split())
INABILITY = set("""
unable fail fails failed failing failure failures struggle struggles
struggling attempt attempts
""".split())
COPULAS = set("be been being am is are was were get gets got getting".split())
FEEL = set("feel feels felt feeling".split())
HAVE = re.compile(
    r"\b(?:have|has|had|having|experience|experienced|experiencing|"
    r"encounter|encountered|encountering)(?:\s+(?:a|an|any|no|some|much|"
    r"more|less|enough|serious|considerable|great|significant|such|little|"
    r"the|lot|of)){0,4}\s*$"
)
NEED = re.compile(
    r"\b(?:need|needs|needed|needing|require|requires|required)"
    r"(?:\s+(?:some|any|more|additional|extra|further|my|your|our|their|"
    r"his|her)){0,2}\s*$"
)


def predict(token, before, start):
    # Complete a word split into multiple tokenizer pieces.
    if token[:1].isalpha() and token[:1].isascii():
        tail = re.search(r"[A-Za-z]+$", before)
        if tail:
            token = tail[0] + token
            before = before[:tail.start()]
    w = token.strip().lower()
    words = re.findall(r"[a-z]+(?:['’][a-z]+)?", before.lower())
    prev = words[-1] if words else ""
    have = bool(HAVE.search(before.lower()))
    need = bool(NEED.search(before.lower()))
    value = 0.002 + (-0.28 if start else 0)
    if w in {"when", "while"}:
        value += 0.52 if w == "when" else 0.39
        if prev in FEELINGS or prev in {
            "careful", "caution", "cautious", "problem", "problems", "trouble"
        }:
            value += 1.06
        if prev.endswith("error") or prev == "errors":
            value += 1.71 if w == "when" else 4.37
    if w in ADVERSITY:
        value += 0.79
        if w in {"error", "errors", "mistake", "mistakes"}:
            value += -0.48
        if w in {"problem", "problems"}:
            value += -0.27
        if w in {"challenge", "challenges"}:
            value += -0.44
        if prev in {"the", "this", "that", "these", "those", "which", "whose"}:
            value += -0.52
            if w in {"issue", "issues"}:
                value += 0.26
        if prev in {"any", "no"}:
            value += 1.34
        if have:
            value += 4.51
            if prev in {"any", "no", "a", "an"}:
                value += -1.88
        if w in DIFFICULTY:
            value += 0.43 + (1.0 if have else 0)
            if have and w in {"trouble", "troubles"}:
                value += 1.04
        if w in {"error", "errors"} and prev in {
            "syntax", "parsing", "parse", "compilation", "runtime", "fatal",
            "import", "type", "connection"
        }:
            value += 1.79
    if w == "help":
        value += 0.27 + (4.08 if need else 0)
        if need and prev in {"need", "needs", "needing"}:
            value += 2.35
        if prev in {"for", "seek", "sought", "seeking", "request",
                    "requesting", "some", "any"}:
            value += 2.34
    if w == "assistance":
        value += 0.61 + (1.81 if need else 0)
    if w in {"question", "questions"} and have:
        value += -0.07 + 2.21
    if w in FEELINGS:
        value += 0.09 + 0.79
        if any(v in FEEL | COPULAS for v in words[-2:]):
            value += 0.07
        if prev in FEEL | COPULAS:
            value += 0.47
        if prev in FEEL:
            value += 1.64
    if w == "time":
        if prev in {"hard", "harder", "difficult", "tough"}:
            value += 5.45
        if prev == "first":
            value += 1.21
    if w in {"careful", "cautious"}:
        value += 1.14
    if w in {"correctly", "properly", "successfully"}:
        value += 0.62
    if w in {"cannot", "unable", "unexpected"}:
        value += {"cannot": 0.32, "unable": 0.8,
                  "unexpected": 0.77}[w]
        if w != "unexpected" and token.strip()[:1].isupper():
            value += 1.18
    if w in {"couldnt", "cant"} or (
        w in {"'t", "’t", "nt", "not"} and
        prev in {"can", "could", "ca", "couldn", "couldnt"}
    ):
        value += 0.79
    if w == "wrong":
        value += 0.29
        if prev == "went":
            value += 4.53
        if prev in {"doing", "done", "something", "nothing", "anything"}:
            value += 1.39
    if w == "during" and (prev.endswith("error") or prev == "errors"):
        value += 3.11
    if w in {"in", "with"}:
        head = words[-2] if prev in COPULAS and len(words) > 1 else prev
        if head in ADVERSITY:
            value += 1.57 if w == "in" else 0.73
        if prev in {"help", "assistance"}:
            value += 0.7
            if re.search(r"\b(?:need|needs|needed)(?:\s+\w+){0,2}"
                         r"\s+(?:help|assistance)\s*$", before.lower()):
                value += 1.5
    if w == "to":
        if prev in INABILITY or (prev == "able" and "not" in words[-4:]):
            value += 1.11
        if re.search(r'''(?:^|["':])\s*[Uu]nable\s*$''', before):
            value += 3.29
    if w == "unable" and re.search(r'''["':]\s*$''', before):
        value += 0.84
    if w == "ao":  # Portuguese: on/upon/when.
        value += 0.89
    if len(token) >= 2 and set(token) == {"·"}:
        value += -1.34
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    before = "" if start else carry[1]
    token = prefix.token_strings[-1]
    value = predict(token, before, start)
    return (doc, (before + token)[-120:]), float(value)

"""A partial predictor of lexical and formatting cues at document openings.

An initial 'Title:' colon gets a large positive value; selected code-opening
patterns and primitive-type keywords get negative values. Other rules cover
initial grammatical word forms and visible formatting marks. Most contextual
variation is not explained: unmatched tokens stay at the background mean.
"""
READS = ()

ARTICLES = frozenset(('a', 'an', 'the'))
NEGATION = frozenset(('no', 'not'))
MODALS = frozenset(('may', 'might', 'must', 'shall', 'should', 'will', 'would'))
PERFECT_AUXILIARIES = frozenset(('have', 'has', 'had'))
FLOATING_TYPES = frozenset(('float', 'double'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '')
    _, position, previous, tail = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    word = stripped.lower()
    value = -0.002

    # Typographic delimiters, not the contents they enclose.
    if len(stripped) >= 2 and set(stripped) == {'·'}:
        value = -1.45
    elif stripped in ('`', '``'):
        value = -0.04 * len(stripped)
    elif token == 'document' and tail.endswith(('\\begin{', '\\end{')):
        value = 0.55

    if position == 0:
        if token.startswith('/*'):
            value = -0.65 if '\n' in token else -1.59
        elif token.startswith('//'):
            value = -1.80 if '\n' in token else -0.68
        elif token.startswith('#!'):
            value = -0.90
        elif token and set(token) == {'#'}:
            value = -0.25
        elif token and set(token) == {'\t'}:
            value = 0.50
        elif token and set(token) == {' '}:
            value = -0.30
        elif token in ('\n', '\n\n'):
            value = -0.13 if len(token) == 1 else 0.19
        elif word in ARTICLES:
            value = -0.20 if stripped.istitle() else 0.02
        elif word in NEGATION or word in MODALS:
            value = -0.48
        elif word == 'if':
            value = -0.50
        elif word == 'each':
            value = -0.75
        elif word in ('and', 'or'):
            value = 0.28
        elif word in PERFECT_AUXILIARIES:
            value = 0.32
        elif token in FLOATING_TYPES or token == 'void':
            value = -2.60
        elif token == 'bool':
            value = -4.25
        elif token == 'int':
            value = -3.17
        elif token == 'string':
            value = -1.91
        elif token.startswith('.*') and not stripped[2:].strip(';'):
            value = 1.40
        elif token.startswith('/') and token[1:].isalpha():
            value = 0.40
    elif position == 1:
        if previous == 'Title' and token == ':':
            value = 3.28
        elif previous == 'package' and token in (' com', ' org'):
            value = -2.29 if token == ' com' else -0.59
        elif previous == '<?' and token == 'php':
            value = -1.14

    return (doc, position + 1, token, (tail + token)[-24:]), value

"""An orthographic detector for the -ive adjective/derivative family.

Negative responses are strongest on exposed suffix fragments and on action /
control adjectives (executive, reactive, protective, etc.). Whole English
words are weaker, especially frequent words. The rules include -if, -iv/-ív,
Romance/German inflections, Russian -ив and its following adjective ending,
and a few analogous adjective endings in other scripts. This is a suffix
heuristic, not a full morphological parser.
"""
import re
import codecs
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
ROOTS = ('give', 'live', 'drive', 'strive', 'arrive', 'derive', 'survive',
         'revive', 'dive', 'hive', 'five', 'olive', 'archive', 'retrieve', 'motive',
         'receive', 'perceive', 'deceive', 'conceive', 'believe', 'achieve')
CONTROL = ('execut', 'react', 'proact', 'pass', 'adapt', 'protect',
           'construct', 'direct', 'prevent', 'correct', 'predict')
LEXICALIZED = ('posit', 'negat', 'object', 'effect', 'mot', 'derivat',
               'comprehens')
RUSSIAN_ENDINGS = {
    'ный', 'ные', 'ного', 'ным', 'ными', 'ных', 'ной', 'но',
    'ная', 'ное', 'ную', 'на', 'ны', 'ые', 'ый', 'ой', 'ы',
}
LATIN_ENDINGS = {'i', 'a', 'e', 'o', 'os', 'as', 'en', 'em', 't', 'n',
                 'ni', 'u', 'ita', 'itat', 'ement', 'amente', 'ly', 'isme'}
FAMILY = re.compile(r'iv(e|es|ely|eness|ity|ities|idad|ismo|ist|ism|iste|'
                    r'amente|ement|a|as|o|os|i|en|er|em)?$')

@lru_cache(maxsize=8192)
def token_part(token):
    # Strip Latin accents, but preserve other scripts' letters and marks.
    low = token.lower().replace('\x00', '')
    low = ''.join(
        ''.join(d for d in unicodedata.normalize('NFKD', c)
                if not unicodedata.combining(d))
        if 'LATIN' in unicodedata.name(c, '') else c for c in low)
    match = re.search(r'[^\W\d_]+$', low)
    return low, match[0] if match else ''


def english(stem, end, part, word, joined):
    if joined and part.startswith('activ') and word != part:
        return -2.09
    fragment = part in ('ive', 'ives', 'ively', 'iveness', 'ivity')
    if (joined or not stem) and (
            fragment or len(part) <= 5 or zipf_frequency(part, 'en') < 2):
        if stem.endswith(LEXICALIZED):
            return -0.95
        if stem.endswith(CONTROL + ('interact',)):
            return -8.46 if end == 'es' else -4.57
        if end == 'e':
            return -3.26 if part in ('ive', 've') else -1.81
        return {'es': -2.3, 'ely': -2.6,
                'eness': -4.77, 'ity': -2.29,
                'ities': -2.29}[end]
    if end in ('ity', 'ities', 'eness'):
        return -0.13
    frequency = max(0.0, zipf_frequency(word, 'en') - 3.5)
    if end == 'ely':
        if stem in ('alternat', 'respect'):
            return 0.0
        return min(0.2, -1.8 + 1.1*frequency)
    if stem.endswith(CONTROL):
        return -3.42
    if stem in ('act', 'interact'):
        return -1.09 if stem == 'act' else -2.35
    return min(0.2, -0.93 + 0.48*frequency)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    pending = carry[2] if carry is not None and carry[0] == doc else b''
    raw = pending + prefix.token_bytes[-1]
    token, used = codecs.utf_8_decode(raw, 'ignore', False)
    pending = raw[used:]
    low, part = token_part(token)
    if not low:
        return (doc, previous, pending), 0.0
    joined = bool(part and part == low and previous)
    word = (previous + part)[-100:] if joined else part
    value = 0.0
    if joined and ((previous.endswith('ив') and part in RUSSIAN_ENDINGS)
                   or (len(previous) >= 5 and previous.endswith('iv')
                       and previous != 'antiv' and part in LATIN_ENDINGS)):
        value = -2.33
    elif part.endswith(('性', '式')):
        value = -0.21
    elif word.endswith('ив') and word != previous:
        stem = word[:-2]
        if joined and len(stem) >= 3 and stem.endswith(('т', 'с')):
            value = (-5.17 if stem.endswith(('ат', 'ит', 'ет', 'кт'))
                     else -2.76)
        elif part == 'актив':
            value = -2.23
    elif 'if' in part and len(word) >= 5 and re.search(r'[ts]ifs?$', word):
        value = -3.16
    elif 'iv' in part or part in ('v', 've', 'ves'):
        m = FAMILY.search(word)
        if m:
            stem, end = word[:m.start()], m[1] or ''
            root = any((stem+'ive').endswith(r) for r in ROOTS)
            if not root:
                if end in ('e', 'es', 'ely', 'eness', 'ity', 'ities'):
                    value = english(stem, end, part, word, joined)
                elif word.endswith(('activ', 'aktiv')):
                    value = -2.23
                elif joined and stem != 'ant' and stem.endswith(
                        ('t', 's', 'i')):
                    if end in ('en', 'er', 'em'):
                        value = -7.18
                    elif end == '':
                        value = -4.43
                    elif end in ('amente', 'ement', 'idad'):
                        value = -2.29
                    elif stem.endswith(('posit', 'negat', 'exclus', 'mot',
                                        'obiett', 'objet')):
                        value = -2.32
                    else:
                        value = -4.59
    # Greek -tik-, Polish -ywn-/-cyj-, and Dutch -ief counterparts.
    elif part.endswith('κ') and len(word) > 4 and word.endswith('τικ'):
        value = -3.11
    elif 'w' in part and word.endswith(
            ('tyw', 'syw', 'zyw', 'tywn', 'sywn', 'cyj', 'syj')):
        value = -3.52
    # Japanese/Korean phonetic renderings of the -tive sound.
    elif token.endswith('ティブ') or (
            token.endswith(('ブ', 'ベ', '브'))
            and previous.endswith(('ティ', '티'))):
        value = -6.98
    elif 'ief' in part and len(word) > 4 and word.endswith(('tief', 'sief')):
        value = -1.7
    return (doc, word, pending), float(value)

"""Approximate local syntax and familiar phrase completions.

Positive rules recognize displayed timestamps, TeX alignment, CommonJS imports,
publication metadata, and several English collocations. TeX proof and align
environment boundaries are negative. Some document-initial role labels, titles
and syntax markers have separate offsets. Everything else is zero: the many
small background activations are not modeled.
"""
import calendar
import re

READS = ()
MONTHS = '|'.join(calendar.month_abbr[1:])
TIMESTAMP = re.compile(
    r'\b\d{1,2} (?:' + MONTHS + r'),? (?:19|20)\d{2}, [0-2]\d$'
)
ORDINAL_TIMESTAMP = re.compile(
    r'\b(?:' + MONTHS + r') \d{1,2}(?:st|nd|rd|th) '
    r'(?:19|20)\d{2}, [0-2]\d$'
)
PHRASES = {
    'staff': ('chief of', 1.25),
    'significance': ('level of', 2.3),
    'motion': ('equations of', 2.3),
    'operations': ('order of', 1.8),
    'tasks': ('solve', 1.35),
    'state': ('equation of', 0.98),
}


def activation(s, before, first):
    word = s.strip()
    low = word.lower()
    if first:
        if s == 'user':
            return 2.27
        if s == 'assistant':
            return 1.45
        if s == '<|endoftext|>':
            return -2.48
        if s == '\\"' or s == '__':
            return 1.5
        if s in {'const', 'var', 'function', 'class'}:
            return 1.5
        if word in {'Sir', 'Saint', 'St', 'Captain'}:
            return 1.6
    if s == ':':
        if ORDINAL_TIMESTAMP.search(before):
            return 1.0
        if TIMESTAMP.search(before):
            return 1.75
        if re.search(r'\b[A-Z]\.,\s*(?:18|19|20)\d{2}$', before):
            return 1.4
    if s == '\n\n' and re.search(r'(?:Posted|Published) on$', before):
        return 1.5
    if '&' in s and not word.strip('&='):
        tex = re.search(
            r'\\(?:begin|frac|hat|bar|geq?|leq?|to|int|sum|dd|pars|cr|nonumber)\b'
            r'|\$\$', before
        )
        if tex:
            relation = re.search(
                r'(?:[^\s:]=|\\(?:to|geq?|leq?|approx|equiv|sim))\s*$', before
            )
            if relation or ('=' in s and word.endswith('&')):
                return 4.5
            if re.search(r'(?:\\cr|\\begin\{(?:aligned|split)\})\s*$', before):
                return 1.6
            if re.search(r'\\\\(?:\[[^\]]*\])?\s*$', before):
                return 1.0
    if low == 'require' and re.search(r'=\s*$', before):
        return 2.4 if re.search(r'}\s*=\s*$', before) else 0.87
    if low in PHRASES:
        phrase, value = PHRASES[low]
        if before.lower().rstrip().endswith(phrase):
            return value
    if low in {'mc', 'const'} and re.search(r'=\s*$', before):
        return 2.3 if low == 'mc' else 4.4
    if word == '/=' and before.rstrip().endswith('='):
        return 3.7
    if low in {'proof', 'align'}:
        if re.search(r'\\end\{$', before):
            return -2.4 if low == 'proof' else -0.21
        if re.search(r'\\begin\{$', before):
            return -1.7 if low == 'proof' else -0.87
    if low == 'quote' and before.endswith('['):
        return 3.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    s = prefix.token_strings[-1]
    return (doc, (before + s)[-240:]), activation(s, before, first)

"""Positive cues for post boundaries and author/profile metadata.

Chat-header newlines have a modest response. Forum signatures, comment
separators, attribution labels, and profile widgets have larger responses.
Ordinary text is near zero. These are approximate surface rules, not a
complete account of the component's context-sensitive amplitudes.
State resets between documents. Timestamp colons are a negative cue;
decorative middle dots also depend on whether they begin the document.
"""
import re

READS = ()
MONTH = r'\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b'


def response(s, previous, tail, line, position, initial_dots, forum):
    word = s.strip()
    if s == '\n':
        if previous == '<|im_end|>':
            return 0.34
        if previous in ('<tool_call>', '<tool_response>', '<think>'):
            return 0.58
        if previous in ('assistant', 'user', 'system'):
            if '<|im_start|>' in tail[-40:]:
                return 0.54
        if re.search(MONTH, line) and re.search(r'\d{1,2}:\d{2}$', line):
            return 1.2
    if word == ':' and previous == 'Title' and position < 4:
        return 9.05
    if word == ':' and previous == 'Joined':
        return 1.65
    if word == ':' and re.search(r'\bat \d{1,2}$', line):
        if forum or 'Commented' in line or '–\xa0' in line:
            return -1.8
    if s and set(s) == {'·'} and len(s) >= 2:
        return 2.21 if initial_dots else 0.25

    # Plain-text comment separators and signature rules.
    joined = line + s
    if re.fullmatch(r'_{16,18}\s*', joined) and '_' in s:
        return 4.7 if '\n' in s else 2.0
    if re.fullmatch(r'-{6}\s*', joined) and '\n' in s:
        return 4.4 if tail.endswith('\n\n') else 0.0
    if re.fullmatch(r'~{2,3}\s*', joined):
        before = tail[:-len(line)] if line else tail
        if before.endswith('\n\n'):
            return 5.0 if '\n' in s else 2.9
    if s == '\xa0' and previous.strip() in ('–', '—'):
        return 13.5
    if word == '–' and line.strip() == '[' and tail[:-1].endswith('\n\n'):
        return 10.3  # A forum's bracketed collapse control.
    if word == '–':
        dated = re.search(r'\bat \d{1,2}:\d{2}\n$', tail)
        if not line.strip() and (forum or dated):
            return 14.0
        if s.startswith(' ') and re.search(r'[.!?][\s"”]*$', tail):
            return 5.0

    # Attribution and revision labels, distinct from uses in ordinary prose.
    if word.lower() == 'by':
        if re.search(r'(?:posted|asked)\s*$', tail, re.I):
            return 2.6
        if re.search(r'(?:photo|liked|\d\s*[AP]M)\s*$', tail, re.I):
            return 1.7
        if re.search(r'(?:edited|submitted)\s*$', line, re.I):
            return 2.0
    if word.lower() == 'edited':
        if re.search(r'\blast\s*$', tail, re.I) or not line.strip():
            return 3.4
    if word == 'ed' and previous.strip() == 'Comment':
        return 4.5
    if word == 'Comment' and line.strip() == 'Author':
        return 3.1
    if word == 'Comment' and not line.strip():
        return 1.5
    if word == 'on' and previous.strip() == 'Posted':
        return 1.9
    if word == 'wrote' and len(line.split()) <= 2:
        return 0.5
    if word == 'Updated' and tail.endswith('Question\n'):
        return 5.2
    if word == 'ED' and previous == 'MARK':
        if 'BOOK' in tail[-15:]:
            return 4.9
    if word == '_closed' and tail.endswith('<issue'):
        return 5.5

    # Recognizable forum profile and navigation widgets.
    if word == 'putation' and line.strip() == 'Re':
        return 3.8
    if word == 'privilege' and previous.strip() == 'Next':
        return 7.0
    if word in ('revised', 'awarded', 'comment') and forum:
        if re.search(r'\b\d{1,2}\s*$', line):
            return 5.8
    if word == 'permalink':
        return 3.7
    if word == 'Tags' and re.search(r'\bShow\s*$', line):
        return 5.8
    if word == 'udos' and line.strip() == 'K':
        return 2.4
    if word == 'Joined' and not line.strip():
        return 1.0
    if word == 'Follow' and not line.strip() and 'Posts:' in tail:
        return 1.6
    if word == 'badges' and re.search(r'\b(?:gold|silver|bronze)\s*$', tail):
        return 3.1
    if word == 'views' and re.fullmatch(r'\s*\d+[kKmM]?\s*', line):
        return 1.2
    if word == '•':
        if re.search(r'\d{1,2}:\d{2}\s*\n$', tail):
            return 4.6
        return 0.08
    if word == '@':
        if line.strip() == '•':
            return 7.8
        if not line.strip() and forum:
            return 6.0
    if word in ('##', '###', '####', '#####'):
        return 0.16
    if s == ' <' and re.fullmatch(r'\s*\d*\s*[-+]?\s*', line):
        return 0.60
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0, True, False)
    _, previous, tail, line, position, initial_dots, forum = carry
    s = prefix.token_strings[-1]
    value = response(s, previous, tail, line, position, initial_dots, forum)
    forum = forum or (s == '\xa0' and previous.strip() == '–')
    forum = forum or (s == 'ed' and previous.strip() == 'Comment')
    forum = forum or (s == 'putation' and line.strip() == 'Re')
    tail = (tail + s)[-300:]
    line = (line + s).rsplit('\n', 1)[-1][-200:]
    initial_dots = initial_dots and bool(s) and set(s) == {'·'}
    return (doc, s, tail, line, position + 1, initial_dots, forum), value

programs.haiku:
"""Forum and web boilerplate that leads into an author name, as one component's trigger.

The component fires on the few tokens that open an attribution or sign-off line on web
forums, comment threads and pages: the dash and non-breaking space before a commenter's
name, "Posted by", "Last edited by", "Show Tags", "[#permalink]", "Kudos", "Title:"
headers, and divider rules. It is weakly positive on the newline after a chat-turn marker.
Everything else is treated as silent (0).
"""

READS = ()

SENTENCE_END = (".", "?", "!")
DIVIDERS = ("------\n", "_________________\n\n", "~~", "~\n", "_\n")
TURN_END = ("user", "assistant", "<tool_call>", "<tool_response>", "<|im_end|>")


def _prev_in_doc(prefix):
    n = len(prefix)
    return n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if _prev_in_doc(prefix) else ""
    prev2 = prefix.token_strings[-3] if len(prefix) > 2 and _prev_in_doc(prefix) else ""
    value = 0.0
    if cur == "\xa0" and prev in (" –", "–"):
        value = 15.0  # non-breaking space right after a comment's dash sign-off
    elif cur in (" –", "–") and prev.rstrip()[-1:] in SENTENCE_END:
        value = 5.0  # dash after a sentence: sign-off before an author name
    elif cur in DIVIDERS:
        value = 4.0  # divider rule under a forum post header
    elif cur == "··" and prev == "··":
        value = 2.2  # runs of middle-dot filler
    elif cur == ":" and prev == "Title":
        value = 9.0 if prev2 == "<|endoftext|>" else 3.0  # web-page title header
    elif cur in (" Tags",) and prev in (" Show", "Show"):
        value = 6.0  # "Show Tags" UI text
    elif cur == "permalink" and prev in ("[#", " [#"):
        value = 4.0  # "[#permalink]" post link
    elif cur == "udos" and prev == "K":
        value = 2.3  # "Kudos" counter
    elif cur == " @" and prev == "•":
        value = 7.6  # bullet then @mention
    elif cur == "ed" and prev in ("Comment", " Comment", "MARK"):
        value = 4.5  # "Comment edited" / "Comment marked"
    elif cur == " edited" and prev in ("Last", "last"):
        value = 5.0  # "Last edited by"
    elif cur == " by" and prev.strip() in ("Posted", "posted"):
        value = 3.0  # "Posted by"
    elif cur == "\n" and prev in TURN_END:
        value = 0.5  # weak: newline after a chat-turn marker
    return carry, float(value)

programs.sol:
"""Local possession, production, and event-predicate heuristics.

HAVE and grouped acquisition/creation/manifestation verbs receive positive
weights. Selected WITH/TO/IN/FOR constructions and event-noun OF complements
extend this to multiword relations. Alphabetic token fragments are joined;
noun, passive, and code-like contexts reduce the English signal.
Translated HAVE forms, restricted Chinese dictionary glosses/aspect particles,
and Russian reflexive endings provide limited multilingual coverage.
This approximates semantic families, not the remaining lexical variation.
"""
import re
from functools import lru_cache
import wordnet
import cedict

READS = ()

# Lemmas, grouped by the relation expressed rather than tokenizer spelling.
GROUPS = (
    (0.95, 'receive obtain acquire gain earn derive'),
    (0.65, 'create produce generate form develop establish implement '
     'achieve introduce'),
    (1.35, 'possess exhibit undergo wear'),
    (0.65, 'display reveal demonstrate'),
    (0.60, 'cause trigger induce'),
    (0.55, 'give provide supply grant award issue send'),
    (0.65, 'perform commit'),
    (0.42, 'make'),
    (0.33, 'take'),
    (0.26, 'do put'),
    (0.50, 'want'),
    (0.20, 'need include contain'),
)
GROUPS = tuple((a, frozenset(words.split())) for a, words in GROUPS)

# Common forms of the verb HAVE in French, German, Italian, Spanish,
# Portuguese, and Scandinavian languages.
HAVE_FORMS = frozenset('''
avoir avons avez ont avait avaient avais
haben habe hast hat habt hatte hatten ha ho hai hanno abbiamo avete
haber han hemos habeis había habían habia habian tenho tinha
tener tiene tienen tenía tenia har havde hade
avere aver avevo avevi aveva avevamo avevate avevano
avuto avuta avuti avute avrei avresti avrebbe avremmo avreste avrebbero
avions aviez aurai auras aura aurons aurez auront
avait avaient aurais aurait aurions auriez auraient
'''.split())
BE = frozenset('am is are was were be been being'.split())
DETERMINERS = frozenset('a an the this these those my your his her our their'.split())

@lru_cache(maxsize=32768)
def predicate(word):
    if not word.isascii() or not word.isalpha():
        return 0.0, False, False
    bases = set(wordnet.base_forms(word, 'verb'))
    if 'have' in bases:
        return {'has': 1.0, 'had': 1.4, 'having': 1.0}.get(word, 1.25), True, False
    value = max((a for a, group in GROUPS if bases & group), default=0.0)
    if 'get' in bases:
        value = 0.65
    if 'show' in bases:
        value = 1.65 if word == 'showed' else 0.2
    if 'exhibit' in bases and word.endswith('ed'):
        value = 2.5
    if 'experience' in bases:
        value = 1.3 if word.endswith(('ed', 'ing')) else -0.1
    noun = 'noun' in wordnet.parts_of_speech(word)
    return value, bool(bases), noun


@lru_cache(maxsize=8192)
def chinese_predicate(word):
    """Possession, creation and acquisition in Chinese dictionary glosses."""
    if word in {'了', '过', '過'}:
        return 0.5  # perfective / experienced-action markers
    if word in {'着', '著'}:
        return 0.75  # ongoing-state marker
    if word == '有':
        return 0.7
    if len(word) < 2:
        return 0.0  # single characters have too many non-verbal uses
    value = 0.0
    for gloss in cedict.glosses(word):
        match = re.match(r'to ([a-z]+)\b', gloss)
        if not match:
            continue
        root = match.group(1)
        if root in {'have', 'possess'}:
            value = max(value, 0.7)
        elif root in {
            'create', 'produce', 'generate', 'implement', 'establish',
            'provide', 'supply', 'obtain', 'acquire', 'receive', 'arise',
            'occur', 'happen', 'emerge', 'develop', 'achieve'
        }:
            value = max(value, 0.95)
        if gloss.startswith(('to carry out', 'to set up', 'to found')):
            value = max(value, 0.9)
    return value

@lru_cache(maxsize=16384)
def relation_link(word, previous):
    """An object can follow a whole construction, not just a bare verb."""
    if word not in {'with', 'of', 'to', 'in', 'for'}:
        return 0.0
    bases = set(wordnet.base_forms(previous, 'verb'))
    if word == 'with':
        if bases & {'equip', 'face', 'arm'}:
            return 2.5
        if bases & {'provide', 'supply', 'fit', 'adorn', 'come'} or previous == 'up':
