        if previous == 'going' or bases & {'lead', 'subject', 'entitle'}:
            return 1.25
        if previous in {'pursuant', 'about', 'rise', 'right'}:
            return 0.9
        if bases & {'expose', 'belong', 'correspond'}:
            return 0.5
    if word == 'in':
        if 'engage' in bases:
            return 2.6
        if 'result' in bases:
            return 1.4
        if bases & {'involve', 'participate', 'invest'}:
            return 0.55
    if word == 'for':
        if 'allow' in bases:
            return 1.4
        if bases & {'need', 'petition', 'apply', 'ask'}:
            return 0.9
        if 'look' in bases:
