def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', False)
    _, old, before, join = carry
    token = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+$', token)
    word = match.group().lower() if match else ''
    continuing = bool(word and token.isalpha() and join)
    if continuing:
        word = (old + word)[-64:]
        previous = before
    else:
        previous = old or before
    value, verb, noun = predicate(word)
    if verb and word not in {'have', 'has', 'had', 'having'}:
        if word.endswith('ing'):
            value += 0.15
        if word == 'got':
            value += 0.75
        elif word == 'getting':
            value += 0.35
        if previous in BE and (word.endswith('ed') or word in {
            'made', 'given', 'taken', 'shown', 'gotten', 'done'
        }):
            value *= 0.3
        elif noun and not word.endswith('ing') and previous in (
            DETERMINERS | {'of', 'with', 'by', 'from', 'at', 'in', 'on'}
        ):
            value *= 0.15
    if (word in HAVE_FORMS and match and match.group().islower()
            and (continuing or token[0].isspace())):
        value = 1.8
    if token.strip() in {"'a", '’a'}:
        value = 2.0
    if word == 'a' and previous in {'il', 'elle', 'ils', 'elles', 'qui'}:
        value = 2.5
    if token.strip() in {"'ai", '’ai'}:
        value = 3.4
    if token.strip() in {"'ve", '’ve'}:
        value = 1.5
    if token.strip().isalpha() and not token.isascii():
        value = max(value, chinese_predicate(token.strip()))
    if word.endswith((
        'ться', 'ется', 'ются', 'ится', 'ятся', 'аться'
    )):
        value = 0.9
    if match and match.group()[0].isupper() and not continuing:
        value *= 0.6
    if word in {'experience', 'experiences'} and previous in {
        'may', 'might', 'can', 'could', 'will', 'would', 'must', 'they',
        'we', 'you', 'i', 'he', 'she', 'it', 'also', 'often', 'sometimes'
    }:
        value = 2.0
    link = relation_link(word, previous)
    if link:
        value = max(value, link)
    if any(ch in token for ch in '._/\\'):
        value = 0.0
    elif word and token[0].isalpha() and not continuing:
        value *= 0.35
    if not word:
        previous = '' if token.strip() else previous
    return (doc, word, previous, bool(word)), float(value)

"""Approximate a mostly negative spelling feature for PROP-like word stems.

Large responses occur on `prop` and on word pieces completing that stem,
especially `prop` + `yl`. Several complete English word families are
attenuated instead; the rule is orthographic, not a shared word meaning.
There are weaker ROP/Cyrillic variants and a separate repeated-middle-dot
response. Carry keeps only a trailing word fragment, reset per document.
