import re

READS = ()


def stem_value(s, spaced):
    if 'prop' not in s:
        return 0.0
    if re.search(r'propert|propriét|proprietà|propiedad', s):
        return 0.15 if spaced else -0.2
    if 'propos' in s and 'proposition' not in s and not s.endswith('propos'):
        return -0.3
    if 'propag' in s:
        return -1.8 if 'propaganda' in s else -0.3
    if 'proponent' in s:
        return 0.0
    if 'appropri' in s:
        if s.endswith('ly'):
            return -0.45
        return -1.9 if 'inappropri' in s else -1.25
    if 'proper' in s:
        if s.endswith('ly'):
            return -0.6
        return -2.6 if 'improper' in s else -1.65
    if 'proportion' in s:
        if s.endswith('al') or s.endswith('ate'):
            return -1.2
        return -5.0 if s.endswith('s') else -3.3
    if 'propriet' in s:
        return -3.8 if s.endswith('ary') else -2.1
    if 'proph' in s:
        return -0.4 if 'prophet' in s else -2.2
    if 'propel' in s:
        return -2.8
    if 'propane' in s:
        return -3.7
    if 'propens' in s:
        return -2.6
    if 'propuls' in s:
        return -1.8
    if s.endswith('props') and not spaced:
        return -3.3
    return -4.3 if s[:1] in '._(' else -6.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    s = raw.lower().replace('próp', 'prop')
    continuing = bool(s and s[0].isalpha())
    if raw[:1].isupper() and not raw.isupper():
        continuing = False
    joined = old + s if continuing else s
    value = stem_value(s, bool(raw[:1].isspace()))
    if 'próp' in raw.lower():
        value *= 0.5
    # A stem spanning two tokens has a larger response than an intact word.
    if continuing and 'prop' in joined and 'prop' not in s:
        if 'prop' not in old:
            value = 1.5 * stem_value(joined, True)
            if s == 'rop':
                value = -13.0 if old.endswith('op') else -7.5
            elif joined.endswith('propi'):
                value = -12.0
        elif old.endswith('prop'):
            base = stem_value(joined, True)
            value = base - 0.7 if base > -6.0 else -2.5
            if s == 'yl' or s == 'y':
                value = -9.5
            elif s == 'ri':
                value = -12.0
            elif (re.fullmatch(r'ri[aoe]s?|ias?|os|osition', s)
                  or s.startswith('iet')):
                value = -8.0
        elif old.endswith(('propri', 'propos')):
            value = stem_value(joined, True)
            if joined.startswith(('appropri', 'inappropri')):
