    if continuing and old.endswith('пр'):
        value = -10.0 if s.startswith('оп') else -1.3
        if s.startswith('ив'):
            value = -0.4
    elif value == 0.0:
        if s == 'rop' or (continuing and old.endswith('rop')):
            value = -1.5
        elif (continuing and old.endswith(('ro', 'р'))
              and s in ('p', 'pe', 'оп')):
