        value = -1.75
    match = re.search(r'[^\W\d_]+$', joined, re.UNICODE)
    tail = match.group(0)[-24:] if match else ''
    return (doc, tail), float(value)

"""A spelling-and-phrase detector, dominated by the 'trick/trip/trim' family.

Split spellings receive a stronger response than whole tokens. After a split
' tr', front-vowel continuations tend negative, and o/u tend positive.
English idioms (take care, get rid, keep track) also contribute.
There are small rules for document-initial Title: headers, repeated middle
dots, and the Japanese spelling of trip. State resets between documents.
Other text is approximately silent. This is a coarse lexical approximation,
not a claim that these different triggers have one shared meaning.
"""
import regex
import wordnet
from anyascii import anyascii

READS = ()


def verb_form(word, root):
    return root in wordnet.base_forms(word)


def roman(text):
    # The same spelling pattern is visible in Cyrillic subwords.
    if text == 'Title':
        return text
    if regex.search(r'\p{Script=Cyrillic}', text):
        return anyascii(text).lower()
    return text.lower()


def split_tr(tail):
    """Short subwords expose tr's following vowel more than long ones do."""
    if tail == 'ick':
        return -12.5
    if tail.startswith('ick'):
        return -6.5
    if tail.startswith(('ip', 'yp')) and tail != 'iple':
        return -5.0
    if tail.startswith('ude'):
        return 2.5
    if tail.startswith('uffle'):
        return 4.0
    if tail.startswith('atus'):
        return 4.7
    if tail.startswith(('ou', 'uck', 'unk', 'uss')):
        return -0.5
    if tail.startswith(('im', 'ig')):
        value = -3.3
    elif tail.startswith(('i', 'y', 'e')):
        value = -2.5
    elif tail.startswith(('o', 'u')):
        value = 2.0
    elif tail.startswith(('av', 'ap', 'ail', 'ack', 'act', 'ang', 'ant', 'am')):
        value = -1.7
    elif tail.startswith(('ad', 'af', 'ag', 'al', 'ar', 'as', 'ax', 'az')):
        value = 1.8
    else:
        return 0.0
    return value * (1.0 if len(tail) <= 3 else 0.2)


def lexical(t, p, pp, previous_value, doc_position):
    word, before = t.strip(), p.strip()
    if word == ':' and p == 'Title' and doc_position == 1:
        return 10.7
    if t == '··' and p == t:
        return -0.8
    if word == 'advantage' and verb_form(before, 'take'):
        return -2.2
    if word == 'care':
        if verb_form(before, 'take'):
            return -6.2
        if (before in {'great', 'proper', 'particular', 'good'}
                and verb_form(pp.strip(), 'take')):
            return -4.3
    if word == 'of' and before == 'care' and previous_value < -3:
        return -3.6
    if word in {'rid', 'tired', 'around', 'ready'} and verb_form(before, 'get'):
        if word == 'rid':
            return -3.8
        if word == 'tired':
            return -5.5
        if word == 'around':
            return -2.3
        if word == 'ready':
            return -2.3
    if (word == 'track'
            and (verb_form(before, 'keep') or verb_form(before, 'lose'))):
        return -2.9
    if word == 'trouble' and before in {'have', 'has', 'had', 'having'}:
        return -2.6
    if t == 'トリ':
        return -3.2
    if p == 'トリ' and t == 'ップ':  # Japanese spelling of 'trip'.
        return -8.7
    if word == 'of' and before == 'treatment':
        return -1.0
    if t == 'ed' and before == 'trick':
        return -4.0
    if word == 'careful':
        return -1.7
    if word == 'tired':
        return -1.5
    # Spelling across a token boundary; spaces do not join words.
    if t and not t[0].isspace():
        if p.endswith('tr'):
            softened = p.endswith('str') and not t.startswith('atus')
            scale = 0.4 if softened else 1.0
            val = split_tr(t) * scale
            if t.startswith('ip') and ('round' in pp or 'round' in p):
                val = -10.0
            return val
        if p.endswith('t') and t.startswith('r'):
            short_t = p.strip(' (-') == 't' and t.startswith(('ri', 're'))
            strength = 1.3 if short_t else 0.3
            return split_tr(t[1:]) * strength
        if p == 'r' and pp.endswith('t'):
            return split_tr(t)
        if p.endswith('tre') and t.startswith(('v', 'pp')):
            return -3.7
        if p.endswith('tri') and t.startswith(('ck', 'pp')):
            scale = 0.25 if p.endswith('stri') else 1.0
            return (-7.5 if t.startswith('ck') else -5.5) * scale
        if p.strip() == 't' and t.startswith(('ired', 'iring')):
            return -6.2 if t.startswith('ired') else -4.2
    # Whole-token roots; unrelated longer words are not grouped with them.
    if word in {'trick', 'tricks'}:
        return -7.8 if word == 'trick' else -6.9
    if word == 'tricky':
        return -3.8
    if word in {'trip', 'trips'}:
        if before == 'round':
            return -9.5
        return -2.6 if word == 'trip' else -3.6
    if word in {'trim', 'trimming'}:
        return -2.5 if t.startswith(' ') else -1.0
    if word in {'triangle', 'triangles'}:
        if before == 'right':
            return -2.3
        return -0.4 if word == 'triangle' else -0.7
    if word in {'triple', 'triples', 'triplet', 'triplets', 'tried'}:
        return -0.5
    if word in {'tr', '-tr', 'tri', 'trig', 'tre'}:
        if before == 'right' and word in {'tr', 'tri'}:
            return -5.5
        if before == 'round' and word.endswith('tr'):
            return -5.7
        return {'tr': -0.4, '-tr': -0.7, 'tri': -2.0,
                'trig': -1.5, 'tre': -0.9}[word]
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, 0)
    _, prev, prevprev, prevvalue, position = carry
    current = roman(prefix.token_strings[-1])
    value = lexical(current, prev, prevprev, prevvalue, position)
    return (doc, current, prev, value, position + 1), value

