"""Approximate fragmented sharp-s, long-s, and damaged printed ligatures.

A separate ß token is strongly positive, but a whole word containing ß is
usually not. Historical dafs/mufs spellings have especially large responses.
Long-s split across UTF-8 tokens is negative; its inflectional
continuation is positive. Ambiguous fs spellings need German context or an
OCR correction to a known word. Most ordinary text is assigned zero.
This leaves ordinary lexical and document-start variation unexplained.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
GERMAN_FUNCTION_WORDS = frozenset('''und der die das dem den des nicht ist
sich für mit von auch werden einer einen einem auf'''.split())


@lru_cache(maxsize=2048)
def old_spelling(word):
    """Does replacing OCR f by long-s's modern s recover a common word?"""
    fixed = word.replace('f', 's')
    return len(word) >= 4 and any(
        zipf_frequency(fixed, lang) > max(2.5, zipf_frequency(word, lang) + 0.5)
        for lang in ('de', 'en')
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_bytes, german, tail = '', b'', 0.0, ''
