            value = 1.35
        elif p.endswith('a'):
            value = 2.65
    elif token.strip() == 'daß':
        value = 1.27
    elif token == 'ße':
        value = 1.0
    elif token in ('ßen', 'ßer', 'iß', 'äß', 'üß'):
        value = 0.3
    elif token == 'uß':
        value = 0.7
    elif raw == b'\xbf' and previous_bytes.endswith(b'\xc5'):
        value = -1.65
    elif token == 'afs' and p.strip() == 'd':
        value = 7.1
    elif token == 'ufs' and p.strip() == 'm':
        value = 6.0
    elif token in ('fs', 'ufs', 'afs', 'fst'):
        match = re.search(r'[^\W\d_]+$', tail + token)
        word = match[0].lower() if match else ''
