            value = 1.4
            if p.endswith(('o', 'u')):
                value = 2.7
    elif token == 'ss' and p.endswith(('ä', 'ö', 'ü')):
        value = 1.5 if p.endswith('grö') else 0.6
    elif token == 'uff' and p.strip() == 'a':
        value = 1.05
    elif token == 't' and previous == 'ß':
        value = 1.0
    elif previous == 'ſ' and token in ('en', 'er', 's'):
        value = {'en': 1.0, 'er': 0.5, 's': 1.7}[token]
    elif token == 'en' and p.endswith(('iff', 'uff')) and german > 0.7:
        value = 1.2
