    # for typographic ligatures in extracted PDF text.
    elif raw == b'\xee' and p and p[-1].isascii() and p[-1].isalpha():
        value = 2.0
    elif token == 'Ã' and p.endswith(('a', 'e', 'i', 'o', 'u')):
        value = 1.3
    elif token == 'lig' and tail.endswith('&sz'):
        value = 4.0
    elif token == ';' and tail.endswith('&szlig'):
        value = 5.0

    german = german * 0.98 + (token.startswith(' ') and
                              token.strip().lower() in GERMAN_FUNCTION_WORDS)
