"""Approximate an indefinite-noun-phrase response with local grammar cues.
'a', 'an', 'any', and 'some' receive negative values after conditional,
negative, and existential expressions. 'many a' is particularly strong.
Nearby function words give small corrections. Secondary rules cover integer
types, SQL null/existence checks, and a few quantity/time phrases. Other
tokens receive zero.
These rules capture recurring large training responses, not the many small
token-specific effects. Eight preceding tokens are retained, with a reset
at document boundaries. This is not a full grammatical parser.
"""
import re

READS = ()
INDEFINITE = {' a', ' an', ' any', ' some', ' another'}
NEGATION = {'not', "'t", 'never', 'no'}
COPULAS = {'is', 'are', 'be', "'s", 'am', 'was', 'were', 'been'}
HAVE = {'have', 'has', 'had'}
# Words that can intervene in an existential 'there ... a' construction.
LINKING = set('''is are was were be been being has have had
    live lived stand stood seem seems seemed appear appears appeared
    remain remains remained 's 't isn aren wasn weren hasn hadn haven
    must should can could will would may might not never still also just
    even once ever scarcely only really probably possibly certainly
    perhaps always already usually often sometimes generally many any
    at least and'''.split())


def normalize(token):
    token = token.strip().replace('’', "'")
    if token not in ("'s", "'t"):
        token = re.sub(r'^[^A-Za-z]+(?=[A-Za-z])', '', token)
    return token


def noun_phrase(token, recent):
    word = token.strip()
    p = [normalize(s).lower() for s in reversed(recent)] + [''] * 8
    prev = p[0]
    title = bool(recent) and normalize(recent[-1]).istitle()
    negative = prev in NEGATION
    value = -0.02 + (0.10 if word == 'some' else 0.0)

    if prev == 'if':
        value -= 1.88 + (1.84 if word == 'any' else 0.0)
    elif prev in ('when', 'whenever'):
        value -= 1.04
    elif prev in ('whether', 'unless', 'suppose', 'assuming', 'supposing'):
        value -= 1.08
    if prev in ('if', 'when', 'whenever') and title:
        value -= 0.57
    if negative:
        value -= 0.53 + (0.92 if word == 'a' else 0.0)
        if title:
            value -= 2.20
    if prev == 'without':
        value -= 0.72 + (1.43 if word == 'a' else 0.0)
    if prev in ('exist', 'exists', 'existed'):
        value -= 2.45
    if prev == 'many' and word == 'a':
        value -= 5.70

    for gap, strength in enumerate((1.53, 1.87, 1.39, 0.71)):
        if p[gap] == 'there' and all(x in LINKING for x in p[:gap]):
            value -= strength
            if gap and any(x in NEGATION | {'scarcely'} for x in p[:3]):
                value -= 2.13
            break
    if word == 'another' and (prev == 'if' or 'there' in p[:5]):
        value += 1.04
    if prev in HAVE:
        value -= 0.22
    if prev in COPULAS:
        value -= 0.05
    if prev in HAVE | COPULAS and any(x in NEGATION for x in p[1:3]):
        value -= 0.55
    if prev in ('also', 'still', 'always', 'only', 'even', 'just', 'already'):
        value -= 0.09
    if prev == 'before':
        value -= 0.82
    if prev == 'once':
        value -= 0.67
    if prev == 'such':
        value -= 0.12
    if prev in ('in', 'as', 'for', 'of'):
        value += {'in': 0.17, 'as': -0.07, 'for': 0.11, 'of': -0.05}[prev]
    if prev in ('what', 'how', 'why') or (prev == "'s" and p[1] in ('what', 'how', 'why')):
