def secondary(token, recent):
    """Smaller responses in integer types, SQL, and duration/quantity phrases."""
    p = [normalize(s).lower() for s in reversed(recent)] + [''] * 8
    prev = p[0]
    if token == ' int':
        if prev == 'long':
            return -6.2
        if prev.endswith('unsigned'):
            return -2.8
        if prev.endswith('const'):
