        return 1.6 if prev == 'not' else 0.75 if prev == 'default' else -0.2
    if token == ' null':
        return -0.36 if prev == 'not' else -0.06
    if token == ' EXISTS' and prev in ('not', 'if'):
        return -1.9
    if token == ' ever':
        negative = prev in NEGATION | {'if'}
        negative |= prev == ',' and p[1] in ('never', 'rarely')
        return -3.5 if negative else 0.08
    if token == ' one' and prev in ('no', 'not'):
        return -0.62
