SECONDARY = {' int', 'int', 'INT', 'SIZE', '-age', ' NULL', ' null',
             ' EXISTS', ' ever', ' one', ' Post', ' post', ' Activity',
             ' ago', ' age', ' Age', ' life', ' LIVE', ' does', ' do', ' did'}

