"""Indefinite determiners in non-assertive contexts.

The component goes negative on an indefinite determiner ("a", "an", "any", "some",
"ever") when it comes right after a word that makes the statement existential,
conditional or negated: "there is a", "if a", "without any", "not a", "never a".
Stronger after "there", "if", "without", "never", "whenever"; weaker after "not",
"n't", "when", "whether", "unless". Everywhere else it is near zero.
"""

READS = ()

DETERMINERS = {"a", "an", "any", "some", "ever"}
STRONG = {"there", "if", "without", "never", "whenever"}
WEAK = {"not", "n't", "'t", "’t", "when", "whether", "unless"}
STRONG_WEIGHT = 1.8
WEAK_WEIGHT = 0.9
WINDOW = 2  # the trigger must be at most this many tokens before the determiner


def step(carry, prefix, upstream):
    t = prefix.position
    if prefix.token_strings[t].strip().lower() not in DETERMINERS:
        return carry, 0.0
    strength = 0.0
    for j in range(max(0, t - WINDOW), t):
        if prefix.document_ids[j] != prefix.document_ids[t]:
            continue
        word = prefix.token_strings[j].strip().lower()
        if word in STRONG:
            strength = max(strength, STRONG_WEIGHT)
        elif word in WEAK:
            strength = max(strength, WEAK_WEIGHT)
    return carry, -strength

