def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        last, before, tail, n, paragraphs, includes = '', '', '', 0, 0, 0
    else:
        _, last, before, tail, n, paragraphs, includes = carry
    start = n == 0
    previous = last.replace('\r\n', '\n')
    blank = previous.endswith('\n\n')
    code_imports = 'import ' in tail or 'package ' in tail
    value = 0.0

    # Question/abstract labels and the first paragraph below a title.
    if last == 'Q' and s == ':\n\n':
        value = 5.43
    elif s == ':' and last == 'Title' and n == 1:
        value = 3.48
    elif s == ':' and last == 'Question' and before == '\n\n':
        value = 2.4
    elif s == 'Abstract' and previous == '\n\n':
        value = 2.4
    elif last + s == 'ABSTRACT':
        value = 4.2
    elif s in {'Background', 'BACKGROUND'} and previous == '\n\n':
        value = 1.3
    elif s == 'I' and previous == '\n\n':
        value = 0.65 if paragraphs <= 2 and n < 100 else 0.0
    elif s in {' Overview', ' Question'} and last.strip() in {'##', '###'}:
        value = 1.0
    elif s == ' Summary' and last == ' Solution':
        value = 1.0

    # New groups of declarations, as opposed to continuation lines or prose.
    if s == 'namespace' and blank:
        if '<?php' in tail:
            value = 6.0
        else:
            value = 2.8 if 'using ' in tail else 1.5
    elif s == 'using' and blank:
        value = 2.5 if 'using ' in tail else (1.2 if includes else 0.0)
    elif s == '#include':
        if blank:
            value = 3.8 if includes or '#pragma once' in tail else 0.8
        elif previous.endswith('\n') and includes == 1:
            value = 0.35
    elif s == 'import':
        if start:
            value = -0.84
        elif blank:
            value = 1.3 if code_imports else -0.1
        elif previous.endswith(';\n'):
            value = 0.17
        elif previous.endswith('\n'):
            value = -0.1
    elif s == 'from' and blank and code_imports:
        value = 3.3
    elif s == 'def':
        value = 2.72 if start else (0.06 if previous.endswith('\n') else 0.0)
    elif s == 'use' and blank and '<?php' in tail:
        value = 1.5
    elif s == '//' and start:
        value = -1.32

    # Familiar boilerplate phrases on web pages.
    if s == 'posted' and previous == '\n\n':
        value = 3.4
    elif s == 'Posted' and previous == '\n\n':
        value = 2.0
    elif s == 'Posted' and previous == '\n':
        value = 0.5
    elif s == ' on' and last == 'Posted':
        old_blank = before.replace('\r\n', '\n') == '\n\n'
        value = 9.0 if old_blank else 2.5
    elif s == ' by' and last == 'posted' and before == '\n\n':
        value = 3.0
    elif s in {' on', ' by', ' at'} and last == 'Published':
        value = 1.4
    elif s == ' also' and last == 'See':
        value = -1.05
    elif s == ' Tags' and last == ' Show':
        value = 0.45
    elif s == ' preview' and last == 'This':
        value = 2.4
    elif s == ' shows' and last == ' preview':
        value = 0.7
    elif s == ' pages' and tail.endswith('This preview shows'):
        value = 2.0
    elif s == 'cards' and last == ' Flash':
        value = 1.7
    elif s == '://':
        value = -0.17

    # Single-token indentation at a document's start.
    if start and s.isspace():
        if s == '\t':
            value = 1.62
        elif s == '\xa0':
            value = 1.44
        elif s.startswith('\t') and s[1:].isspace():
            value = 1.1
        elif s in {' ', '   '}:
            value = 0.4
        elif s == '\n\n':
            value = 0.61
        elif s == '\n':
            value = -0.2
    if s and set(s) == {'·'} and len(s) > 1:
        value = -1.17
    if s == '<|endoftext|>':
        return (doc, '', '', '', 0, 0, 0), 0.0
    paragraphs += s.replace('\r\n', '\n').count('\n\n')
    includes += s == '#include'
    state = (doc, s, last, (tail + s)[-700:], n + 1, paragraphs, includes)
    return state, value

programs.haiku:
"""Opening tokens of code files and stock page headers.

Layer-1 MLP output feature that is near zero almost everywhere and spikes on a few
recognisable openings:

* a code keyword that starts a new top-level line after a blank line (`import`,
  `from`, `#include`, `namespace`, `using`, `package`, `def`): about +1;
* stock labels that open a document or a metadata line: `Q:` followed by a blank
  line (+5), `Posted on` (+6), `Published on`, `This preview` (+2.5), `AB|STRACT`
  (+3), `The|orem` (+1.5), `Title:` as the second token of a document (+2);
* web addresses (`www`, `://`, `github`, `.com`): slightly negative;
* a code comment marker (`//`, `/**`) as the first token of a document: negative.

Everything else predicts 0. The rule is causal: it reads only the current token,
the one before it, and how far into its document it sits.
"""

READS = ()

CODE_OPENERS = {"import", "from", "namespace", "#include", "using", "use", "package", "def"}
STOCK_PAIRS = {
    ("Q", ":\n\n"): 5.0,
    ("Posted", " on"): 6.0,
    ("Published", " on"): 1.2,
    ("This", " preview"): 2.5,
    ("AB", "STRACT"): 3.0,
    (" The", "orem"): 1.5,
}
URL_PARTS = {"www", "://", "github", ".com", ".io", ".net"}
COMMENT_STARTS = {"//", "/**"}


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) >= 2 else ""
    # how many tokens before this one are in the same document (capped at 2)
    k = 0
    while k < 2 and len(docs) - 2 - k >= 0 and docs[-2 - k] == docs[-1]:
        k += 1
    if k == 0:
        return carry, (-1.2 if cur in COMMENT_STARTS else 0.0)
    if (prev, cur) in STOCK_PAIRS:
        return carry, STOCK_PAIRS[(prev, cur)]
    if k == 1 and prev == "Title" and cur == ":":
        return carry, 2.0
    if "\n\n" in prev and cur in CODE_OPENERS:
        return carry, 1.0
    if cur.strip() in URL_PARTS:
        return carry, -0.1
    return carry, 0.0

"""Predicate-link detector for layers.1.mlp.down_proj:5689.

The component is a "predicate link" feature. It fires on the word that links a predicate
to the phrase completing it, when a form of "be" (is, are, was, be, ...) comes just before,
or when a past participle comes just before a preposition:
  "is [very] careful", "is [more] [than]", "is [simple] [to] operate",
  "were [born] [in]", "be [proactive] [in] making", "connected [to]", "surprised [by]".
It is strongest on degree words (very, more, less, so, too, not) and on prepositions or "to"
two words after "be" (the "adjective + preposition" slot). It is weak on the word right after
"be", and near zero on infinitive "to" (able to, used to) and on everything else.
On the first token of a document it is slightly negative.
"""

READS = ()

COPULAS = {"is", "are", "was", "were", "be", "been", "being", "am", "become", "becomes",
           "became", "seem", "seems", "remain", "remains", "look", "looks", "get", "gets", "got"}
LINK_PREPOSITIONS = {"to", "in", "by", "for", "with", "at", "from", "into", "under", "within",
                     "as", "than", "of", "on", "through", "about", "among", "between", "over",
                     "against", "across", "after", "before", "upon", "like"}
DEGREE_WORDS = {"very", "more", "less", "most", "too", "so", "much", "little", "quite", "really",
                "rather", "pretty", "particularly", "especially", "not", "well", "increasingly",
                "extremely", "highly", "fairly", "relatively", "somewhat", "substantially",
                "largely", "typically", "generally", "even", "still", "also", "just", "only"}
# words that make a following "to" an infinitive marker ("able to", "used to")
INFINITIVE_LEADS = {"able", "unable", "used", "going", "supposed", "have", "has", "had", "need",
                    "needed", "want", "wanted", "trying", "tried", "how", "likely", "willing"}
ADJECTIVE_ENDINGS = ("ly", "ble", "ive", "ous", "ful", "al", "ic", "ent", "ant", "less")
DETERMINERS = {"the", "a", "an", "no", "this", "that", "these", "those", "my", "his", "her",
               "their", "its", "our", "your", "one", "all", "some", "any", "two"}


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return carry, -0.2  # first token of a document
    words = [s.strip().lower() for s in prefix.token_strings]
    cur = words[t]
    prev = words[t - 1]
    # how many words back the nearest copula is (1 = the word just before), within 3 words
    dist = None
    for k in range(1, 4):
        j = t - k
        if j < 0 or prefix.document_ids[j] != prefix.document_ids[t]:
            break
        if words[j] in COPULAS:
            dist = k
            break
    after_participle = prev.isalpha() and prev.endswith(("ed", "en"))
    if cur in DEGREE_WORDS:
        value = {1: 1.1, 2: 0.8, 3: 0.2}.get(dist, 0.0)
    elif cur in LINK_PREPOSITIONS:
        if cur == "to" and prev in INFINITIVE_LEADS:
            value = 0.1
        elif dist is not None:
            value = {1: 0.4, 2: 0.85, 3: 0.65}.get(dist, 0.25 if dist == 4 else 0.1)
        else:
            value = 0.25 if after_participle else 0.03
    elif cur.isalpha() and cur not in DETERMINERS:
        if dist is not None and cur.endswith(ADJECTIVE_ENDINGS):
            value = {1: 0.8, 2: 0.5, 3: 0.1}[dist]
        else:
            value = {1: 0.25, 2: 0.2, 3: 0.06}.get(dist, 0.0)
    else:
        value = 0.0
    return carry, float(value)

