import unicodedata

READS = ()


def opening_value(token):
    text = token.strip()
    if token.startswith('<|'):
        return 17.5
    if not text:
        if token in (' ', '\t'):
            return -1.2
        if '\n' in token or '\r' in token:
            return 4.5 if token.count('\n') == 1 else 2.5
        return 10.0
    if text.isdecimal():
        return 2.4 + 0.6 * int(text[0])
    if any(c.isalpha() for c in text):
        names = [unicodedata.name(c, '') for c in text]
        if any(script in name for name in names for script in
               ('CJK', 'HIRAGANA', 'KATAKANA', 'HANGUL')):
            return 9.0
        if not text[0].isalpha():
            # Contractions and hyphenated word endings differ from identifiers.
            return 17.0 if text[0] in "'-’" else 10.0
        if token[0].isspace():
            return 17.0
        if text.isascii():
            if len(text) == 1:
                return 11.0
            if text[0].isupper():
                return 18.5
            return 13.0 if len(text) <= 3 else 15.0
        return 17.0
    if text.startswith('#'):
        return 10.0 + 3.0 * min(3, len(text))
    if text.startswith(('//', '/*')):
        return 14.0
    if text[0] in '*`' or len(text) >= 3:
        return 11.0
    if len(text) > 1 or text[0] in ';\\&=+':
        return 8.0
    return 4.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    position = 0 if first else carry[2] + 1
    opening = first or (carry[3] and token == previous)
    value = 0.0
    if opening:
        value = opening_value(token)
    elif token == ' ' and previous and set(previous) == {' '}:
        length = len(previous)
        value = -18.5 + math.log1p(position)
        if length == 1:
            value += 6.7
        elif length == 4:
            value -= 2.1
        elif length >= 5:
            value += 2.6
    elif token == '\t' and previous and set(previous) == {'\t'}:
        value = -4.0 if len(previous) == 1 else -5.8
    elif token == '\xa0' and previous and set(previous) == {'\xa0'}:
        value = -1.6 if len(previous) == 1 else -10.5
    elif (token and previous and set(token) == set(previous) == {'\xa0'}
          and len(token) < len(previous)):
        value = -2.7
