# Width: (line-leading, mid-line, after a written-out \\n).
SPACE_STRENGTH = {
    2: (-1.15, 0.05, -0.66),
    4: (-1.53, -0.19, -1.02),
    8: (-0.82, -0.14, -0.85),
}


