            value = leading - 0.74 / (1 + counts.get(s, 0))
            value += 0.50 * even / (even + odd + 1)
            value += 12.18 * multiples / (position + 1)
            width_scale = 1 if width < 6 else 8 / width
            if '{' in previous:
                value -= 0.43 * width_scale
            if '\t' in s:
                value += 0.43 * width_scale
        elif line.endswith('\\n'):
            value = escaped
        else:
            value = middle
        counts[s] = counts.get(s, 0) + 1
    elif '\n\n' in s:
        punctuation = s.split('\n', 1)[0]
        if s.count('\n') >= 3:
            value = -0.020
        elif not punctuation:
            value = 0.046
        elif not punctuation.strip():
            value = -0.026
        elif punctuation.rstrip().endswith(('.', '?', '!', '。', '！', '？', '”')):
            value = -0.050
        elif punctuation.rstrip().endswith(','):
            value = -0.081
        elif punctuation.rstrip().endswith(':'):
            value = -0.033
        elif punctuation.rstrip().endswith((')', ']', '}', ';', "'", '"', '`')):
            value = -0.075
