        elif word.lower() == 'det':
            value = 0.95
        elif word.lower() in ('es', 'il'):
            scores = [sum(w in language for w in words)
                      for language in
                      (GERMAN, SPANISH, FRENCH, ITALIAN, ENGLISH)]
            german, spanish, french, italian, english = scores
            if word.lower() == 'es':
                value = 0.25
                strong_cue = prev in {'ist', 'wird', 'gibt', 'geht'}
                if (german >= 3 or strong_cue) and german > max(
                        spanish, french, italian, english):
                    value = 5.8 if word == 'es' else 5.2
                    if prev == 'gibt':
                        value = 3.45
                elif spanish > max(german, french, italian, english):
                    value = 0.08
            else:
                value = 0.15
                if french >= 2 and french > max(
                        german, spanish, italian, english):
                    value = 2.4 if word == 'il' else 2.05
                if punctuated and token.strip().startswith(("'", '’')):
                    value = 2.05
    elif word == 'it':
        value = -0.3
    if not recent:
        if word in ('it', 'It'):
            value = 0.45
        elif word == 'I':
            value = -0.6
        elif word == 'es':
            value = -0.18
        elif word == 'Es':
            value = 1.1
    if word == '<' and re.search(r'#\s*include\s*$', recent):
        value = 1.05
    return (doc, (recent + token)[-300:]), value

programs.haiku:
"""Subject-style pronoun detector (layers.1.mlp.down_proj, component 5694).

What it does: the component fires on a pronoun that stands alone as a word and refers
to a thing or an idea: English " it"/" It", German " es"/" Es", French " Il"/" il". It is
the strongest on "it" right after a wh-word ("what it", "when it") or a make/give/find/
have verb ("making it", "made it"), and weaker on "it" after other words. German "es" is
strong everywhere. Object "it" after an imperative verb in code or instructions ("run it",
"remove it") is weaker. First-person " I" gives a small response. Everything else is 0.

Why: the token identity carries most of the signal, and the word before "it" carries most
of the rest. The program reads only the current and previous token, so it is causal.
"""

PRONOUN_IT = {" it", " It", "It"}
PRONOUN_ES = {" es", " Es", "Es"}
PRONOUN_IL = {" il", " Il", "Il"}
FIRST_PERSON_I = {" I", "I"}
WH_WORDS = {"what", "when", "which", "how", "where", "who", "why", "whom"}
MAKE_VERBS = {"make", "made", "makes", "making", "give", "find", "have"}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip()
    if token in PRONOUN_IT:
        value = 2.5 if previous in WH_WORDS | MAKE_VERBS else 1.5
    elif token in PRONOUN_ES:
        value = 2.3
    elif token in PRONOUN_IL:
        value = 1.2
    elif token in FIRST_PERSON_I:
        value = 0.3
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Short k-syllables: vowel-led pieces are negative, consonant-led ones positive.

The strongest negative is k after e; on+k is notably positive.
Complete, familiar words are mostly quiet;
Katakana ku/ki have a stronger vowel-context effect. Turkish soft-g is treated
similarly to k; repeated middle dots have a separate small response. This is a
character-level approximation. Carry remembers the previous token only.
"""
import unicodedata
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
K_LETTERS = frozenset('kкκکكğ')
K_KANA = frozenset('かきくけこカキクケコ')

@lru_cache(maxsize=32768)
def roman(text):
    return anyascii(text.replace('ğ', 'k').replace('Ğ', 'K')).lower()


def predict(text, previous):
    if text == '··':
        return 0.98 if previous.endswith('·') else 0.0
    if not any(c in K_LETTERS or c in K_KANA for c in text.lower()):
        return 0.0
    token = roman(text).strip()
    last = previous[-1:]
    if not any(c.isascii() or c in K_KANA or
               any(script in unicodedata.name(c, '')
                   for script in ('LATIN', 'CYRILLIC', 'GREEK', 'ARABIC',
                                  'HIRAGANA', 'KATAKANA'))
               for c in last):
        previous = ''
    k = token.rfind('k')
    if k < 0:
        return 0.0
    tail = token[k + 1:]
    before = token[k - 1] if k else (
        roman(previous)[-1:] if not text[:1].isspace() else '')
    kana = len(text) == 1 and text in K_KANA
    if kana:
        if text in 'クキ':
            if before == 'e':
                return -5.8
            if before == 'a':
                return -3.0 if text == 'ク' else -1.0
            if before == 'n':
                return 1.5
            return -0.9 if text == 'ク' else -0.5
        return -0.5 if text == 'く' else -0.1
    if len(token) > 5:
        return 0.0
    # Double vowels such as ee and oo usually change or remove this response.
    left = ('' if text[:1].isspace() else roman(previous)) + token[:k]
    if (text.isascii() and previous[-1:].isascii() and len(left) >= 2
            and left[-1] == left[-2] and left[-1] in 'eo'):
        if k == 1 and not text[:1].isspace() and not tail:
            return 1.5
        return 0.0
    # The on+k cluster is strongly positive, including short English words.
    if left.endswith('on') and tail in ('', 's'):
        if k == 0 or zipf_frequency(text.strip(), 'en') > 3.0:
            return 1.4 if tail == 's' and k else 2.5
    if k == 0:
        if (text.isupper() and previous[-1:].islower()
                and len(previous) >= 4
                and zipf_frequency(previous.rsplit('/', 1)[-1], 'en') > 3.0):
            return 0.0
        if len(tail) > 2:
            return 0.0
        scale = 1.0 if tail in ('', 's') else (0.6 if tail == 't' else 0.2)
        if before == 'e':
            return -4.1 * scale
        if before and before in 'aoiuy':
            return -1.0 * scale
        if before.isalpha() and before != 'k':
            value = 0.4 if before == 's' else 0.6
            if len(left) >= 2 and left[-2] in 'ao':
                value = 1.6 if before == 's' else 2.0
            if left.endswith('sh'):
                value = 0.15
            return value * (1.0 if tail in ('', 's') else 0.1)
        return 0.0
    if zipf_frequency(text.strip(), 'en') > 4.0:
        return 0.0
    if before == 'e':
        cyrillic = any('CYRILLIC' in unicodedata.name(c, '') for c in text)
        value = -1.1 if cyrillic else -2.7
        if k >= 3:
            value *= 0.25
        return value * (1.0 if not tail else 0.25)
    if tail not in ('', 's', 't'):
        return 0.0
    if before and before in 'aoiuy':
        return -0.35
    if (len(token) <= 3 and before.isalpha() and before not in 'skc'
            and zipf_frequency(text.strip(), 'en') < 3.0):
        return 0.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, text), float(predict(text, previous))
